  x.globalAlpha = 1;
  // town silhouette foreground
  x.fillStyle = '#0d0913';
  for (let i = 0; i < 12; i++) {
    const bw = 18 + rng() * 30, bh = 16 + rng() * 34, bx = i * 42 - 10, by = 206 - bh;
