/* ══ SOUL KNIGHT PREQUEL: ADVENTURE — pixel ARPG UI ═══════════════════════ */
@font-face { font-family: 'Press'; src: url('../assets/fonts/press-start-2p.woff2') format('woff2'); font-display: swap; }
@font-face { font-family: 'VT'; src: url('../assets/fonts/vt323.woff2') format('woff2'); font-display: swap; }

:root {
  --bg: #06050b;
  --ink: #eee3c8;
  --ink-dim: #c7bda9;
  --muted: #9a8fa8;
  --gold: #f0c05a;
  --gold-hi: #ffe6a8;
  --gold-lo: #b8782a;
  --violet: #b07bff;
  --violet-lo: #5d3b96;
  --red: #ff5f6d;
  --blue: #57b8ff;
  --cyan: #7de8ff;
  --green: #8cf07a;
  --orange: #ff9b4a;
  --pink: #ff5f9d;
  --panel: #151020;
  --panel-2: #1e1730;
  --panel-3: #271d3c;
  --line: #4a3a63;
  --line-hi: #7a629e;
  --shadow: #050409;
  --font-head: 'Press', monospace;
  --font-body: 'VT', monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; overflow: hidden; background: var(--bg); }
body {
  font-family: var(--font-body);
  color: var(--ink);
  font-size: 20px;
  line-height: 1.2;
  -webkit-font-smoothing: none;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  background:
    radial-gradient(ellipse at 50% 40%, #1a1126 0%, #08060e 60%, #040309 100%),
    repeating-linear-gradient(45deg, rgba(255,255,255,.012) 0 2px, transparent 2px 6px);
}
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
img { image-rendering: pixelated; }
kbd {
  font-family: var(--font-head); font-size: 8px; padding: 4px 6px; border: 1px solid #5e4b7c;
  background: #0b0812; color: var(--gold); border-radius: 2px; box-shadow: 0 2px 0 #040308; white-space: nowrap;
}
.hidden { display: none !important; }
::selection { background: var(--violet); color: #fff; }

/* scrollbar */
* { scrollbar-width: thin; scrollbar-color: #5a4680 #120d1c; }
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background: #100b18; }
*::-webkit-scrollbar-thumb { background: #4a3a63; border: 2px solid #100b18; }

/* ── Stage / canvas ────────────────────────────────────────────────────── */
#app, #ui-layer { position: fixed; inset: 0; }
#stage {
  position: fixed; inset: 0; display: flex; align-items: center; justify-content: center;
  background:
    radial-gradient(ellipse at 50% 48%, #1b1228 0%, #0a0710 58%, #030208 100%);
}
#stage::before {
  content: ''; position: absolute; inset: 0; opacity: .5;
  background:
    repeating-linear-gradient(90deg, rgba(255,255,255,.018) 0 1px, transparent 1px 40px),
    repeating-linear-gradient(0deg, rgba(255,255,255,.012) 0 1px, transparent 1px 40px);
}
#game {
  width: min(100vw, calc(100vh * 16 / 9));
  height: min(100vh, calc(100vw * 9 / 16));
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #08060e;
  box-shadow:
    0 0 0 2px #06040a,
    0 0 0 3px #3d2e55,
    0 0 0 5px #090610,
    0 0 70px rgba(176,123,255,.10),
    0 24px 80px rgba(0,0,0,.7);
}
.crt {
  position: fixed; inset: 0; pointer-events: none; z-index: 20; opacity: .35;
  background: repeating-linear-gradient(0deg, rgba(0,0,0,.20) 0 1px, transparent 1px 3px);
  mix-blend-mode: multiply;
}
.vignette {
  position: fixed; inset: 0; pointer-events: none; z-index: 21;
  background: radial-gradient(ellipse at 50% 50%, transparent 45%, rgba(2,1,6,.28) 82%, rgba(2,1,6,.6) 100%);
}

/* ── Screens ───────────────────────────────────────────────────────────── */
.screen { position: absolute; inset: 0; z-index: 30; }
.screen-title { pointer-events: auto; }
.screen-town, .screen-dungeon { pointer-events: none; }
.screen-town button, .screen-town .town-top, .screen-town .town-dock, .screen-town .town-status,
.screen-dungeon button, .screen-dungeon .boss-wrap, .screen-dungeon .joystick { pointer-events: auto; }

/* ── Shared UI ─────────────────────────────────────────────────────────── */
.btn {
  position: relative;
  font-family: var(--font-head); font-size: 10px; letter-spacing: .5px;
  padding: 13px 20px; color: var(--ink); text-transform: uppercase;
  border: 2px solid #5e4b7c;
  background: linear-gradient(180deg, #2a2140, #171022 60%, #120d1c);
  box-shadow: inset 0 2px 0 rgba(255,255,255,.07), inset 0 -2px 0 rgba(0,0,0,.4), 0 3px 0 #040308;
  transition: transform .08s, border-color .12s, color .12s, box-shadow .12s;
  clip-path: polygon(0 5px, 5px 0, calc(100% - 5px) 0, 100% 5px, 100% calc(100% - 5px), calc(100% - 5px) 100%, 5px 100%, 0 calc(100% - 5px));
}
.btn:hover { border-color: var(--gold); color: #ffe6a8; transform: translateY(-1px); box-shadow: inset 0 2px 0 rgba(255,255,255,.1), 0 4px 0 #040308, 0 0 22px rgba(240,192,90,.16); }
.btn:active { transform: translateY(2px); box-shadow: inset 0 2px 0 rgba(255,255,255,.05), 0 1px 0 #040308; }
.btn-primary {
  color: #241708; border-color: #ffe6a8; text-shadow: 0 1px 0 rgba(255,255,255,.35);
  background: linear-gradient(180deg, #ffe08a 0%, #f0c05a 42%, #c88b34 100%);
  box-shadow: inset 0 2px 0 rgba(255,255,255,.55), inset 0 -2px 0 rgba(80,40,0,.4), 0 4px 0 #4a2a08, 0 0 30px rgba(240,192,90,.22);
}
.btn-primary:hover { color: #1b1003; border-color: #fff2cc; box-shadow: inset 0 2px 0 rgba(255,255,255,.6), 0 5px 0 #4a2a08, 0 0 38px rgba(240,192,90,.4); }
.btn-ghost { background: rgba(12,8,20,.55); }
.btn-xl { padding: 17px 26px; min-width: 280px; font-size: 15px; }
.btn-xl small { display: block; font-family: var(--font-body); font-size: 17px; letter-spacing: 1px; margin-top: 6px; opacity: .75; }
.btn-sm { font-size: 8px; padding: 9px 12px; }
.btn:disabled, .btn.disabled { opacity: .4; pointer-events: none; filter: grayscale(.6); }
.icon-btn {
  width: 38px; height: 38px; display: inline-grid; place-items: center;
  font-family: var(--font-head); font-size: 11px; color: var(--ink-dim);
  border: 1px solid #47395f; background: rgba(10,7,16,.72);
  box-shadow: 0 2px 0 rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.05);
  transition: .12s;
}
.icon-btn:hover { color: var(--gold); border-color: var(--gold); background: rgba(40,28,20,.8); }
.icon-btn.off { opacity: .45; }
.chip, .tag, .pill {
  display: inline-flex; align-items: center; gap: 5px;
  font-family: var(--font-head); font-size: 7px; letter-spacing: .4px;
  padding: 6px 8px; border: 1px solid #4a3a63; color: var(--ink-dim);
  background: rgba(10,7,16,.55); white-space: nowrap;
}
.tag.gold { color: var(--gold); border-color: #8a6a2c; }
.tag.red { color: var(--red); border-color: #7a2c3a; }
.tag.blue { color: var(--blue); border-color: #2c5a7a; }
.tag.green { color: var(--green); border-color: #3a6a34; }
.tag.violet { color: var(--violet); border-color: #5d3b96; }
.muted { color: var(--muted); }
.gold-text { color: var(--gold); }
.green-text { color: var(--green); }
.red-text { color: var(--red); }
.blue-text { color: var(--blue); }
.violet-text { color: var(--violet); }
.spacer { flex: 1; }
.divider { height: 1px; background: linear-gradient(90deg, transparent, #4a3a63, transparent); margin: 14px 0; }
.elem-img { width: 15px; height: 15px; vertical-align: -2px; }
.res-img { width: 16px; height: 16px; vertical-align: -3px; }

/* ── Title ─────────────────────────────────────────────────────────────── */
.screen-title { overflow: hidden; }
.title-scrim {
  position: absolute; inset: 0;
  background:
    linear-gradient(90deg, rgba(5,3,10,.95) 0%, rgba(5,3,10,.82) 30%, rgba(5,3,10,.35) 56%, transparent 74%),
    linear-gradient(0deg, rgba(5,3,10,.92) 0%, transparent 28%),
    linear-gradient(180deg, rgba(5,3,10,.6) 0%, transparent 18%);
}
.title-topbar {
  position: absolute; top: 0; left: 0; right: 0; padding: 22px 32px;
  display: flex; align-items: center; justify-content: space-between;
}
.title-mark { display: flex; align-items: center; gap: 10px; font-family: var(--font-head); font-size: 8px; letter-spacing: 1px; color: #9c8db0; }
.mark-diamond { width: 9px; height: 9px; background: var(--gold); transform: rotate(45deg); box-shadow: 0 0 14px rgba(240,192,90,.7); }
.top-actions { display: flex; gap: 8px; }
.title-content {
  position: absolute; left: clamp(28px, 7vw, 130px); top: 50%; transform: translateY(-52%);
  width: min(620px, 72vw); z-index: 2;
}
.title-kicker { display: flex; align-items: center; gap: 12px; font-family: var(--font-head); font-size: 8px; letter-spacing: 2px; color: var(--gold); margin-bottom: 18px; text-shadow: 0 0 12px rgba(240,192,90,.4); }
.title-kicker .rule { width: 42px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.title-kicker .rule:last-child { background: linear-gradient(90deg, var(--gold), transparent); }
.title-logo {
  margin: 0; font-family: var(--font-head); font-weight: 400;
  font-size: clamp(38px, 6.4vw, 76px); line-height: 1.04; letter-spacing: 2px;
  filter: drop-shadow(0 6px 0 rgba(0,0,0,.55)) drop-shadow(0 0 24px rgba(255,180,90,.16));
}
.title-logo span { display: block; }
.logo-soul { color: #f1e7cf; text-shadow: 0 3px 0 #6b5a78, 0 6px 0 #2a1c36, 0 0 24px rgba(230,220,255,.15); }
.logo-knight {
  background: linear-gradient(180deg, #fff0bd 0%, #f0c05a 38%, #d8902f 68%, #9a5c18 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  text-shadow: 0 3px 0 rgba(80,42,8,.55);
  position: relative;
}
.logo-knight::after { content: 'KNIGHT'; position: absolute; inset: 0; color: transparent; -webkit-text-stroke: 1px rgba(70,36,4,.35); }
.title-sub { margin-top: 14px; font-family: var(--font-head); font-size: clamp(9px, 1.15vw, 13px); letter-spacing: 4px; color: #b6a6c8; }
.title-sub .dot { color: var(--gold); font-size: .6em; vertical-align: 2px; margin: 0 4px; }
.title-blurb { margin: 26px 0 30px; font-family: var(--font-body); font-size: clamp(19px, 1.7vw, 27px); line-height: 1.25; color: #bfb1c6; max-width: 470px; text-shadow: 0 2px 8px #000; }
.title-menu { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }
.title-menu-row { display: flex; gap: 10px; flex-wrap: wrap; }
.title-chips { display: flex; gap: 7px; flex-wrap: wrap; margin-top: 28px; max-width: 520px; }
.title-chips .chip { background: rgba(12,8,19,.7); box-shadow: inset 0 0 12px rgba(176,123,255,.05); }
.title-footer {
  position: absolute; left: 32px; right: 32px; bottom: 18px; display: flex; justify-content: space-between;
  font-family: var(--font-head); font-size: 7px; letter-spacing: .5px; color: #6e6280;
}
.title-footer-controls { color: #877a99; }
.title-tip {
  position: absolute; right: 32px; bottom: 44px; max-width: 300px; text-align: right;
  font-size: 18px; color: #9b8fac; text-shadow: 0 2px 6px #000;
}
.title-tip::before { content: ''; display: inline-block; width: 6px; height: 6px; background: var(--gold); transform: rotate(45deg); margin-right: 8px; vertical-align: 1px; box-shadow: 0 0 10px var(--gold); }

/* ── Town UI ───────────────────────────────────────────────────────────── */
.town-top {
  position: absolute; top: 0; left: 0; right: 0; padding: 16px 22px;
  display: flex; align-items: center; gap: 14px;
  background: linear-gradient(180deg, rgba(5,3,10,.82), rgba(5,3,10,.28) 72%, transparent);
}
.brand-mini { display: flex; align-items: center; gap: 10px; min-width: 230px; }
.brand-rune {
  width: 36px; height: 36px; display: grid; place-items: center; flex: 0 0 auto;
  font-family: var(--font-head); font-size: 9px; color: #241708;
  background: linear-gradient(180deg, #ffe08a, #c88b34); border: 1px solid #ffe6a8;
  box-shadow: 0 0 20px rgba(240,192,90,.25);
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
}
.brand-mini b { display: block; font-family: var(--font-head); font-size: 8px; letter-spacing: .8px; color: var(--ink); }
.brand-mini small { display: block; font-size: 16px; letter-spacing: 1px; color: #9487a6; margin-top: 3px; }
.res-bar { display: flex; gap: 6px; flex-wrap: wrap; margin-left: auto; }
.res-pill {
  display: inline-flex; align-items: center; gap: 5px; min-width: 64px;
  padding: 6px 9px; background: rgba(10,7,16,.72); border: 1px solid #423357;
  font-family: var(--font-head); font-size: 8px; color: var(--ink); box-shadow: inset 0 0 14px rgba(176,123,255,.05);
}
.res-pill img { width: 15px; height: 15px; }
.res-pill.mat { border-color: #32435a; }
.res-pill b { font-weight: 400; }
.town-tools { display: flex; gap: 6px; margin-left: 6px; }
.town-status {
  position: absolute; left: 22px; top: 84px; width: 286px; padding: 10px 12px;
  background: linear-gradient(135deg, rgba(16,11,25,.86), rgba(10,7,16,.6));
  border: 1px solid #3f3156; border-left: 2px solid var(--gold);
  box-shadow: 0 10px 30px rgba(0,0,0,.3);
}
.town-level { display: flex; align-items: center; gap: 10px; }
.lvl-ring {
  width: 38px; height: 38px; display: grid; place-items: center; flex: 0 0 auto;
  font-family: var(--font-head); font-size: 11px; color: var(--gold);
  background: radial-gradient(circle at 35% 30%, #3a2b52, #100b18 68%);
  border: 2px solid #6c558e; box-shadow: inset 0 0 12px rgba(176,123,255,.15), 0 0 14px rgba(176,123,255,.1);
  clip-path: polygon(50% 0, 92% 24%, 92% 76%, 50% 100%, 8% 76%, 8% 24%);
}
.town-level small { display: block; font-family: var(--font-head); font-size: 6px; letter-spacing: .6px; color: #8f82a2; }
.town-level strong { display: block; font-family: var(--font-head); font-size: 9px; letter-spacing: .5px; color: var(--ink); margin-top: 4px; }
.town-xp { margin-top: 10px; }
.xp-track { height: 5px; background: #0a0710; border: 1px solid #342846; overflow: hidden; }
.xp-track i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, #6d4bd0, #b07bff); transition: width .3s; box-shadow: 0 0 10px rgba(176,123,255,.6); }
.town-xp span { display: block; margin-top: 4px; font-family: var(--font-head); font-size: 6px; color: #8f82a2; }
.town-quickstats { display: flex; gap: 12px; margin-top: 9px; padding-top: 9px; border-top: 1px solid #2e2440; }
.town-quickstats span { display: flex; flex-direction: column; gap: 2px; }
.town-quickstats i { font-style: normal; font-family: var(--font-head); font-size: 6px; color: #857798; }
.town-quickstats b { font-family: var(--font-head); font-size: 8px; color: var(--ink); font-weight: 400; }
.interact-prompt {
  position: absolute; left: 50%; bottom: 130px; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px; padding: 9px 14px;
  background: rgba(8,6,14,.9); border: 1px solid #6c558e; color: var(--ink);
  font-family: var(--font-head); font-size: 8px; box-shadow: 0 0 30px rgba(176,123,255,.2);
  animation: promptFloat 1.8s ease-in-out infinite;
}
.town-dock {
  position: absolute; left: 50%; bottom: 26px; transform: translateX(-50%);
  display: flex; gap: 8px; padding: 8px; max-width: calc(100vw - 40px);
  background: linear-gradient(180deg, rgba(14,9,22,.86), rgba(7,5,12,.92));
  border: 1px solid #40315a; box-shadow: 0 14px 50px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.05);
  overflow-x: auto;
}
.dock-btn {
  position: relative; display: flex; flex-direction: column; align-items: center; gap: 3px;
  width: 96px; padding: 8px 6px 7px; color: var(--ink);
  border: 1px solid #342744; background: linear-gradient(180deg, #1b1428, #110c19);
  transition: .14s; flex: 0 0 auto;
}
.dock-btn:hover { border-color: var(--c, var(--gold)); transform: translateY(-2px); background: linear-gradient(180deg, #241a35, #151020); box-shadow: 0 8px 22px rgba(0,0,0,.4), 0 0 20px rgba(176,123,255,.08); }
.dock-glyph {
  width: 31px; height: 24px; display: grid; place-items: center;
  font-family: var(--font-head); font-size: 8px; color: var(--c, var(--gold));
  border: 1px solid var(--c, var(--gold)); background: rgba(0,0,0,.3);
  box-shadow: inset 0 0 12px color-mix(in srgb, var(--c, var(--gold)) 16%, transparent), 0 0 12px color-mix(in srgb, var(--c, var(--gold)) 10%, transparent);
}
.dock-btn b { font-family: var(--font-head); font-size: 7px; letter-spacing: .3px; font-weight: 400; margin-top: 2px; }
.dock-btn small { font-size: 15px; color: #8e809f; line-height: 1; }
.town-hint { position: absolute; right: 24px; bottom: 8px; display: flex; gap: 14px; font-family: var(--font-head); font-size: 6px; color: #6f637f; }
.town-hint span { display: flex; align-items: center; gap: 5px; }

/* ── Dungeon HUD ───────────────────────────────────────────────────────── */
.hud { position: absolute; inset: 0; pointer-events: none; }
.hud-top-left { position: absolute; top: 15px; left: 18px; display: flex; gap: 8px; align-items: flex-start; }
.portrait {
  position: relative; width: 48px; height: 48px; flex: 0 0 auto;
  background: linear-gradient(180deg, #2a2038, #120c1c); border: 2px solid #6c558e;
  box-shadow: 0 0 0 2px #0a0710, inset 0 0 16px rgba(176,123,255,.14);
  display: grid; place-items: center;
  clip-path: polygon(50% 0, 100% 18%, 100% 82%, 50% 100%, 0 82%, 0 18%);
}
.portrait-helm {
  width: 22px; height: 24px; display: block;
  background: linear-gradient(180deg, #e7eef7 0 34%, #9aa6b5 34% 56%, #5e6a7a 56%);
  clip-path: polygon(18% 100%, 10% 44%, 22% 10%, 50% 0, 78% 10%, 90% 44%, 82% 100%, 66% 100%, 62% 62%, 38% 62%, 34% 100%);
  box-shadow: 0 0 12px rgba(125,232,255,.2);
}
.portrait-helm::after { content: ''; position: absolute; left: 20px; top: 23px; width: 8px; height: 3px; background: #65e0ff; box-shadow: 0 0 7px #65e0ff; }
.portrait i {
  position: absolute; right: -5px; bottom: -4px; min-width: 20px; height: 16px; padding: 0 3px;
  display: grid; place-items: center; font-family: var(--font-head); font-size: 7px; font-style: normal;
  color: #241708; background: var(--gold); border: 1px solid #ffe6a8; box-shadow: 0 2px 0 #4a2a08;
}
.bars { display: flex; flex-direction: column; gap: 4px; padding-top: 1px; }
.bar { position: relative; height: 16px; width: 200px; background: #0a0710; border: 1px solid #4c3a63; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,.5); }
.bar i { display: block; height: 100%; width: 100%; transition: width .16s linear; background-size: 8px 100%; }
.bar.hp i { background: linear-gradient(180deg, #ff8a92 0%, #e84858 38%, #a61d2b 100%); box-shadow: inset 0 0 0 1px rgba(255,255,255,.08), 0 0 12px rgba(232,72,88,.4); }
.bar.mp { width: 150px; height: 12px; }
.bar.mp i { background: linear-gradient(180deg, #9adcff 0%, #3f9ce0 42%, #1e5d9a 100%); box-shadow: 0 0 10px rgba(87,184,255,.35); }
.bar.xp { width: 200px; height: 4px; border-color: #2e2440; margin-top: 1px; }
.bar.xp i { background: linear-gradient(90deg, #6d4bd0, #c78cff); box-shadow: 0 0 8px rgba(199,140,255,.5); }
.bar::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 9px, rgba(0,0,0,.18) 9px 10px); pointer-events: none; }
.bar-label { position: absolute; left: 5px; top: 50%; transform: translateY(-50%); z-index: 2; font-family: var(--font-head); font-size: 6px; color: rgba(255,255,255,.75); text-shadow: 0 1px 0 #000; }
.bar b { position: absolute; right: 5px; top: 50%; transform: translateY(-50%); z-index: 2; font-family: var(--font-head); font-size: 6px; font-weight: 400; color: #fff; text-shadow: 0 1px 0 #000, 0 0 4px #000; }
.bar.mp b { font-size: 5px; }
.hud-top-right { position: absolute; top: 14px; right: 18px; display: flex; align-items: flex-start; gap: 8px; }
.minimap-box { position: relative; width: 92px; background: rgba(8,6,14,.7); border: 1px solid #4a3a63; padding: 4px; box-shadow: 0 4px 18px rgba(0,0,0,.5); }
#minimap { width: 80px; height: 80px; display: block; image-rendering: pixelated; }
.mini-meta { display: flex; justify-content: space-between; gap: 4px; margin-top: 3px; font-family: var(--font-head); font-size: 5px; color: #9b8fac; }
.run-purse { display: flex; flex-direction: column; gap: 4px; }
.run-purse span { display: flex; align-items: center; gap: 4px; padding: 4px 7px; background: rgba(8,6,14,.72); border: 1px solid #3d2f52; font-family: var(--font-head); font-size: 7px; }
.run-purse img { width: 13px; height: 13px; }
.hud-top-right .icon-btn { width: 34px; height: 34px; }
.boss-wrap {
  position: absolute; left: 50%; bottom: 112px; transform: translateX(-50%);
  width: min(520px, 64vw); padding: 7px 10px 9px;
  background: linear-gradient(180deg, rgba(14,8,18,.9), rgba(8,4,10,.82));
  border: 1px solid #6c2a3a; box-shadow: 0 0 30px rgba(255,60,80,.14), 0 8px 24px rgba(0,0,0,.5);
}
.boss-head { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }
.boss-tag { font-family: var(--font-head); font-size: 6px; padding: 3px 5px; color: #1a0609; background: #ff5f6d; }
.boss-head b { font-family: var(--font-head); font-size: 8px; font-weight: 400; letter-spacing: .6px; color: #ffd7dc; flex: 1; }
.boss-head em { font-style: normal; font-family: var(--font-head); font-size: 6px; color: #c98a96; }
.boss-track { height: 12px; background: #14060a; border: 1px solid #5a2030; overflow: hidden; position: relative; }
.boss-track i { display: block; height: 100%; width: 100%; background: linear-gradient(180deg, #ff9aa3, #e03a54 40%, #8a1026); box-shadow: 0 0 14px rgba(255,60,90,.45); transition: width .2s; }
.boss-track::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 30px, rgba(0,0,0,.28) 30px 31px); }
.battle-banner { position: absolute; top: 88px; left: 50%; transform: translateX(-50%); text-align: center; pointer-events: none; }
.battle-banner b { display: block; font-family: var(--font-head); font-size: clamp(12px, 1.6vw, 18px); letter-spacing: 2px; color: var(--gold); text-shadow: 0 3px 0 #1a0e06, 0 0 24px rgba(240,192,90,.4); animation: bannerIn .35s ease-out; }
.battle-banner span { display: block; margin-top: 6px; font-family: var(--font-head); font-size: 7px; letter-spacing: 1.5px; color: #c3b4cf; }
.action-cluster { position: absolute; right: 20px; bottom: 20px; width: 206px; height: 164px; }
.action-btn {
  position: absolute; display: flex; flex-direction: column; align-items: center; justify-content: center;
  border-radius: 50%; border: 2px solid #6c558e; color: var(--ink);
  background: radial-gradient(circle at 36% 28%, #3a2d52, #171022 62%, #0c0814);
  box-shadow: 0 4px 0 #040308, inset 0 2px 0 rgba(255,255,255,.10), inset 0 -8px 16px rgba(0,0,0,.45);
  transition: transform .07s, filter .1s; pointer-events: auto; touch-action: none;
}
.action-btn:active { transform: scale(.94); filter: brightness(1.2); }
.action-btn span { font-family: var(--font-head); font-size: 7px; letter-spacing: .5px; }
.action-btn em.keycap { position: absolute; right: 0; bottom: 2px; font-style: normal; font-family: var(--font-head); font-size: 6px; color: #b9a9cc; background: rgba(6,4,10,.85); padding: 2px 3px; border: 1px solid #3d2f52; }
.action-btn.attack { width: 78px; height: 78px; right: 0; bottom: 0; border-color: #ff8b93; background: radial-gradient(circle at 36% 28%, #ff8b93, #c72a3a 48%, #6e0d1b 100%); box-shadow: 0 5px 0 #39040c, inset 0 2px 0 rgba(255,255,255,.28), 0 0 26px rgba(255,60,90,.22); }
.action-btn.attack span { font-size: 12px; color: #fff; text-shadow: 0 2px 0 #5a0a14; }
.action-btn.attack em.keycap { color: #ffd7dc; }
.action-btn.dodge { width: 54px; height: 54px; right: 88px; bottom: 4px; border-color: #7fd4ff; background: radial-gradient(circle at 36% 28%, #3e7fa8, #174665 55%, #0a2233); }
.action-btn.dodge span { color: #c9efff; font-size: 6px; }
.action-btn.skill { width: 54px; height: 54px; overflow: hidden; }
.action-btn.skill img { width: 38px; height: 38px; image-rendering: pixelated; }
.action-btn.skill .cost { position: absolute; left: 2px; top: 1px; font-family: var(--font-head); font-size: 5px; font-weight: 400; color: #9adcff; }
#btn-skill1 { right: 18px; bottom: 90px; }
#btn-skill2 { right: 82px; bottom: 84px; }
.action-btn.potion { width: 40px; height: 40px; border-color: #3d6a52; background: radial-gradient(circle at 36% 28%, #274d36, #12251a 70%); }
.action-btn.potion.hp { right: 150px; bottom: 4px; }
.action-btn.potion.mp { right: 148px; bottom: 52px; border-color: #2e5a7a; background: radial-gradient(circle at 36% 28%, #23445e, #0e2233 70%); }
.action-btn.potion span { font-size: 6px; color: #d6ffe6; }
.action-btn.potion.mp span { color: #cfeeff; }
.action-btn.potion b { font-family: var(--font-head); font-size: 8px; font-weight: 400; margin-top: 2px; }
.action-btn .cd { position: absolute; inset: -1px; border-radius: 50%; pointer-events: none; background: conic-gradient(rgba(4,2,8,.78) var(--p, 0%), transparent 0); }
.action-btn.skill .cd { border-radius: 0; }
.joystick { position: absolute; left: 22px; bottom: 22px; width: 104px; height: 104px; touch-action: none; display: none; }
.joy-base { position: absolute; inset: 0; border-radius: 50%; background: radial-gradient(circle, rgba(30,22,44,.72), rgba(8,6,14,.42)); border: 2px solid rgba(122,98,158,.55); box-shadow: inset 0 0 24px rgba(0,0,0,.5), 0 0 18px rgba(176,123,255,.08); }
.joy-base::after { content: ''; position: absolute; inset: 26px; border-radius: 50%; border: 1px dashed rgba(122,98,158,.32); }
.joy-knob { position: absolute; left: 50%; top: 50%; width: 42px; height: 42px; border-radius: 50%; transform: translate(-50%, -50%); background: radial-gradient(circle at 35% 30%, #7f68a6, #2a2040 60%, #141020); border: 2px solid #9a7fc4; box-shadow: 0 4px 10px rgba(0,0,0,.6), inset 0 2px 0 rgba(255,255,255,.15); }
.joystick.active .joy-knob { background: radial-gradient(circle at 35% 30%, #b99cf0, #403060 60%, #1c1530); }
.hud-footer {
  position: absolute; left: 50%; bottom: 5px; transform: translateX(-50%);
  display: flex; gap: 12px; align-items: center; font-family: var(--font-head); font-size: 6px; letter-spacing: .4px;
  color: #7b6e8c; white-space: nowrap;
}
.hud-footer #biome-label { color: #a696b8; }
.hud-footer .hud-combo { color: var(--gold); }
.hud-footer .hud-hint { color: #615670; }

/* ── Modal & panel chrome ──────────────────────────────────────────────── */
.modal { position: fixed; inset: 0; z-index: 60; display: grid; place-items: center; }
.modal-shade { position: absolute; inset: 0; background: rgba(4,2,9,.78); backdrop-filter: blur(3px) saturate(.9); animation: fadeIn .18s; }
.panel {
  position: relative; z-index: 1; width: min(1040px, 94vw); max-height: 88vh;
  display: flex; flex-direction: column;
  background:
    linear-gradient(180deg, rgba(38,28,58,.97), rgba(18,13,29,.99) 15%, rgba(13,9,21,.995)),
    repeating-linear-gradient(45deg, rgba(255,255,255,.02) 0 2px, transparent 2px 8px);
  border: 2px solid #5a4680;
  box-shadow: 0 0 0 4px #090610, 0 0 0 6px #3a2d50, 0 26px 90px rgba(0,0,0,.72), inset 0 1px 0 rgba(255,255,255,.07), inset 0 0 80px rgba(176,123,255,.035);
  animation: panelIn .22s cubic-bezier(.2,.9,.3,1);
}
.panel::before { content: ''; position: absolute; left: 16px; right: 16px; top: 0; height: 2px; background: linear-gradient(90deg, transparent, var(--gold), transparent); opacity: .7; }
.panel::after { content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: linear-gradient(90deg, transparent, #6c558e, transparent); opacity: .5; }
.panel-head {
  display: flex; align-items: flex-start; gap: 14px; padding: 18px 22px 14px;
  border-bottom: 1px solid #332747; flex: 0 0 auto;
  background: linear-gradient(180deg, rgba(52,38,78,.55), transparent);
}
.panel-head .ph-icon { width: 42px; height: 42px; display: grid; place-items: center; flex: 0 0 auto; font-family: var(--font-head); font-size: 10px; color: var(--gold); border: 1px solid #6c558e; background: #100b18; box-shadow: inset 0 0 18px rgba(176,123,255,.12); }
.panel-head h2 { margin: 0; font-family: var(--font-head); font-size: 15px; letter-spacing: 1px; color: var(--ink); font-weight: 400; }
.panel-head .ph-sub { margin-top: 6px; font-size: 18px; color: #a293b4; line-height: 1.15; }
.panel-head .ph-right { margin-left: auto; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
.panel-close { width: 34px; height: 34px; flex: 0 0 auto; display: grid; place-items: center; font-family: var(--font-head); font-size: 10px; color: #b6a6c8; border: 1px solid #4a3a63; background: #0d0915; transition: .12s; }
.panel-close:hover { color: #fff; border-color: var(--red); background: #2a0f16; }
.panel-body { padding: 18px 22px 24px; overflow: auto; flex: 1 1 auto; }
.panel-foot { padding: 12px 22px; border-top: 1px solid #332747; display: flex; align-items: center; gap: 10px; flex: 0 0 auto; background: rgba(8,5,14,.4); }
.res-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; font-family: var(--font-head); font-size: 8px; color: #b6a6c8; }
.res-row span { display: inline-flex; align-items: center; gap: 5px; }
.res-row img { width: 15px; height: 15px; }

/* ── Forge ─────────────────────────────────────────────────────────────── */
.forge-layout { display: grid; grid-template-columns: 280px 1fr; gap: 16px; }
.equipped-card { position: relative; padding: 14px; background: linear-gradient(180deg, rgba(61,45,90,.4), rgba(15,10,24,.5)); border: 1px solid #6c558e; }
.equipped-card::before { content: 'EQUIPPED'; position: absolute; top: -7px; left: 10px; padding: 0 6px; font-family: var(--font-head); font-size: 6px; color: var(--gold); background: #171020; }
.big-weapon { display: flex; align-items: center; gap: 12px; }
.big-weapon .wicon { width: 76px; height: 76px; display: grid; place-items: center; background: radial-gradient(circle, rgba(176,123,255,.14), transparent 70%); border: 1px solid #4a3a63; }
.big-weapon .wicon img { width: 64px; height: 64px; }
.big-weapon h3 { margin: 0 0 4px; font-size: 24px; line-height: 1; font-weight: 400; }
.big-weapon .w-meta { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.weapon-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 3px 12px; margin-top: 10px; font-size: 18px; }
.weapon-stats div { display: flex; justify-content: space-between; border-bottom: 1px dotted #2e2440; padding-bottom: 2px; }
.weapon-stats b { color: var(--ink); font-weight: 400; }
.weapon-stats span { color: #9586a8; }
.affix-list { margin-top: 8px; display: flex; flex-direction: column; gap: 3px; }
.affix-list span { font-size: 17px; color: #cdbff0; }
.affix-list span::before { content: '✦'; margin-right: 6px; color: var(--violet); }
.upgrade-row { display: flex; align-items: center; gap: 8px; margin-top: 12px; flex-wrap: wrap; }
.upgrade-cost { font-family: var(--font-head); font-size: 7px; color: var(--gold); display: flex; align-items: center; gap: 4px; }
.upgrade-cost img { width: 12px; height: 12px; }
.owner-list { display: flex; flex-direction: column; gap: 6px; }
.owner-list-head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.owner-list-head h3 { margin: 0; font-family: var(--font-head); font-size: 9px; font-weight: 400; color: #c8b9dc; }
.weapon-row {
  display: flex; align-items: center; gap: 10px; padding: 7px 8px;
  background: rgba(10,7,16,.5); border: 1px solid #322744; transition: .1s;
}
.weapon-row:hover { border-color: #6c558e; background: rgba(35,26,52,.5); }
.weapon-row.equipped { border-color: var(--gold); background: linear-gradient(90deg, rgba(240,192,90,.10), rgba(10,7,16,.4)); }
.weapon-row img { width: 38px; height: 38px; flex: 0 0 auto; }
.weapon-row .wr-info { flex: 1; min-width: 0; }
.weapon-row .wr-name { font-size: 19px; line-height: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.weapon-row .wr-sub { display: flex; gap: 6px; align-items: center; margin-top: 4px; font-family: var(--font-head); font-size: 6px; color: #9586a8; flex-wrap: wrap; }
.weapon-row .wr-dps { text-align: right; font-family: var(--font-head); font-size: 8px; color: var(--green); flex: 0 0 auto; }
.weapon-row .wr-dps small { display: block; color: #81738f; font-size: 5px; margin-bottom: 3px; }
.weapon-row .wr-actions { display: flex; gap: 4px; flex: 0 0 auto; }
.empty-state { padding: 26px; text-align: center; color: #897b9a; border: 1px dashed #3d2f52; font-size: 19px; }

/* ── Skills / stats ────────────────────────────────────────────────────── */
.skills-layout { display: grid; grid-template-columns: 250px 1fr; gap: 16px; }
.stats-panel { background: rgba(10,7,16,.45); border: 1px solid #322744; padding: 12px; }
.stats-panel h3, .skill-equip h3 { margin: 0 0 10px; font-family: var(--font-head); font-size: 9px; font-weight: 400; color: #c8b9dc; }
.stat-row { display: flex; align-items: center; gap: 8px; padding: 5px 0; border-bottom: 1px dotted #2a2139; }
.stat-row:last-child { border: 0; }
.stat-abbr { width: 34px; font-family: var(--font-head); font-size: 8px; color: var(--sc, var(--gold)); }
.stat-info { flex: 1; }
.stat-info b { display: block; font-size: 18px; font-weight: 400; }
.stat-info small { display: block; font-size: 15px; color: #9183a2; margin-top: 1px; }
.stat-val { font-family: var(--font-head); font-size: 9px; color: var(--ink); }
.plus-btn { width: 24px; height: 24px; display: grid; place-items: center; font-family: var(--font-head); font-size: 9px; color: #241708; background: linear-gradient(180deg, #ffe08a, #c88b34); border: 1px solid #ffe6a8; box-shadow: 0 2px 0 #4a2a08; }
.plus-btn:disabled { opacity: .28; box-shadow: none; }
.points-banner { display: flex; align-items: center; gap: 8px; padding: 8px 10px; margin-bottom: 10px; background: rgba(240,192,90,.08); border: 1px solid #7a5a22; font-family: var(--font-head); font-size: 7px; color: var(--gold); }
.skill-equip { margin-bottom: 12px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.skill-slots { display: flex; gap: 8px; }
.skill-slot { width: 56px; height: 56px; display: grid; place-items: center; background: #0b0812; border: 1px solid #4a3a63; position: relative; }
.skill-slot img { width: 40px; height: 40px; }
.skill-slot small { position: absolute; bottom: 2px; font-family: var(--font-head); font-size: 5px; color: #8b7d9e; }
.skill-slot.empty::before { content: '+'; font-family: var(--font-head); font-size: 14px; color: #4a3a63; }
.skill-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.branch { background: linear-gradient(180deg, rgba(30,22,45,.55), rgba(10,7,16,.35)); border: 1px solid #322744; padding: 10px; }
.branch-head { display: flex; align-items: center; gap: 7px; margin-bottom: 10px; }
.branch-glyph { width: 28px; height: 28px; display: grid; place-items: center; font-family: var(--font-head); font-size: 9px; color: var(--bc); border: 1px solid var(--bc); background: rgba(0,0,0,.3); }
.branch-head b { display: block; font-family: var(--font-head); font-size: 8px; font-weight: 400; color: var(--bc); }
.branch-head small { display: block; font-size: 15px; color: #8b7d9e; margin-top: 2px; }
.skill-node { position: relative; padding: 8px; margin-bottom: 18px; border: 1px solid #322744; background: rgba(8,5,13,.55); transition: .12s; }
.skill-node:last-child { margin-bottom: 0; }
.skill-node::after { content: ''; position: absolute; left: 50%; bottom: -19px; width: 1px; height: 18px; background: #322744; }
.skill-node:last-child::after { display: none; }
.skill-node.unlocked { border-color: var(--bc); box-shadow: inset 0 0 20px color-mix(in srgb, var(--bc) 8%, transparent); }
.skill-node.available { border-color: #6a5a22; animation: nodePulse 2.2s infinite; }
.skill-node.locked { opacity: .45; filter: grayscale(.4); }
.skill-node-top { display: flex; align-items: center; gap: 7px; }
.skill-node-top img { width: 30px; height: 30px; }
.skill-node-top b { display: block; font-size: 18px; font-weight: 400; }
.skill-node-top small { display: block; font-family: var(--font-head); font-size: 5px; color: #9a8cab; margin-top: 2px; }
.skill-node p { margin: 7px 0 7px; font-size: 16px; line-height: 1.18; color: #b7a9c6; }
.skill-node .node-actions { display: flex; gap: 4px; }
.node-req { font-family: var(--font-head); font-size: 5px; color: #7d6f90; margin-top: 4px; }

/* ── Shop ──────────────────────────────────────────────────────────────── */
.shop-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 10px; }
.shop-item { display: flex; gap: 10px; padding: 10px; background: rgba(10,7,16,.5); border: 1px solid #322744; transition: .12s; }
.shop-item:hover { border-color: #6c558e; background: rgba(32,24,48,.55); }
.shop-icon { width: 42px; height: 42px; flex: 0 0 auto; display: grid; place-items: center; font-family: var(--font-head); font-size: 9px; color: var(--sc, var(--gold)); border: 1px solid var(--sc, var(--gold)); background: rgba(0,0,0,.28); }
.shop-icon img { width: 30px; height: 30px; }
.shop-info { flex: 1; min-width: 0; }
.shop-info b { display: block; font-size: 20px; font-weight: 400; line-height: 1; }
.shop-info small { display: block; font-size: 15px; color: #9183a2; margin-top: 3px; line-height: 1.1; }
.shop-buy { display: flex; flex-direction: column; align-items: flex-end; justify-content: space-between; gap: 6px; }
.price { font-family: var(--font-head); font-size: 7px; color: var(--gold); display: flex; align-items: center; gap: 3px; white-space: nowrap; }
.price img { width: 12px; height: 12px; }

/* ── Codex ─────────────────────────────────────────────────────────────── */
.codex-filters { display: flex; gap: 5px; flex-wrap: wrap; margin-bottom: 12px; align-items: center; }
.filter-btn { font-family: var(--font-head); font-size: 6px; padding: 7px 8px; border: 1px solid #3d2f52; background: #0d0915; color: #9a8cab; }
.filter-btn.active { border-color: var(--gold); color: var(--gold); background: rgba(240,192,90,.08); }
.codex-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(66px, 1fr)); gap: 6px; }
.codex-cell { position: relative; aspect-ratio: 1; display: grid; place-items: center; background: rgba(8,5,13,.65); border: 1px solid #2d223e; cursor: pointer; transition: .1s; padding: 4px; }
.codex-cell:hover { border-color: var(--cc, var(--gold)); transform: translateY(-2px); box-shadow: 0 4px 10px rgba(0,0,0,.4); }
.codex-cell img { width: 100%; height: 100%; object-fit: contain; }
.codex-cell.locked { opacity: .28; filter: grayscale(1) brightness(.6); }
.codex-cell.owned { border-color: var(--cc, #4a3a63); background: radial-gradient(circle, color-mix(in srgb, var(--cc, #4a3a63) 12%, transparent), rgba(8,5,13,.65) 70%); }
.codex-cell .cc-check { position: absolute; right: 2px; top: 1px; font-size: 11px; color: var(--gold); }
.codex-stats { display: flex; gap: 10px; font-family: var(--font-head); font-size: 7px; color: #a696b8; margin-bottom: 12px; flex-wrap: wrap; }
.weapon-detail { display: grid; grid-template-columns: 140px 1fr; gap: 18px; }
.weapon-detail .wd-icon { display: grid; place-items: center; background: radial-gradient(circle, color-mix(in srgb, var(--wc, #b07bff) 16%, transparent), rgba(8,5,13,.7) 70%); border: 1px solid var(--wc, #4a3a63); min-height: 140px; }
.weapon-detail .wd-icon img { width: 110px; height: 110px; }
.weapon-detail h3 { margin: 0 0 4px; font-size: 28px; font-weight: 400; line-height: 1; }
.wd-tags { display: flex; gap: 5px; flex-wrap: wrap; margin: 8px 0; }

/* ── Gate ──────────────────────────────────────────────────────────────── */
.gate-layout { display: grid; grid-template-columns: 1fr 300px; gap: 16px; }
.gate-section h3 { margin: 0 0 9px; font-family: var(--font-head); font-size: 9px; font-weight: 400; color: #c8b9dc; }
.gate-biomes { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.gate-card { position: relative; padding: 11px; border: 1px solid #322744; background: linear-gradient(135deg, rgba(30,22,45,.5), rgba(8,5,13,.45)); cursor: pointer; transition: .12s; }
.gate-card:hover { border-color: var(--bc); }
.gate-card.selected { border-color: var(--bc); background: linear-gradient(135deg, color-mix(in srgb, var(--bc) 16%, transparent), rgba(8,5,13,.5)); box-shadow: 0 0 24px color-mix(in srgb, var(--bc) 12%, transparent); }
.gate-card.locked { opacity: .42; cursor: not-allowed; }
.gate-card b { display: block; font-family: var(--font-head); font-size: 8px; font-weight: 400; color: var(--bc); }
.gate-card small { display: block; margin-top: 5px; font-size: 16px; line-height: 1.1; color: #a293b4; }
.gate-card .gc-elems { display: flex; gap: 3px; margin-top: 7px; }
.gate-card .gc-elems img { width: 13px; height: 13px; }
.diff-list { display: flex; flex-direction: column; gap: 7px; }
.diff-card { display: flex; align-items: center; gap: 9px; padding: 9px 10px; border: 1px solid #322744; background: rgba(8,5,13,.5); cursor: pointer; }
.diff-card.selected { border-color: var(--dc); background: color-mix(in srgb, var(--dc) 12%, transparent); }
.diff-pip { width: 8px; height: 8px; background: var(--dc); transform: rotate(45deg); box-shadow: 0 0 10px var(--dc); }
.diff-card b { display: block; font-family: var(--font-head); font-size: 7px; font-weight: 400; color: var(--dc); }
.diff-card small { display: block; font-size: 15px; color: #9a8cab; margin-top: 2px; }
.gate-side { background: rgba(10,7,16,.45); border: 1px solid #322744; padding: 13px; }
.gate-summary { display: flex; flex-direction: column; gap: 8px; font-size: 18px; }
.gate-summary div { display: flex; justify-content: space-between; gap: 8px; border-bottom: 1px dotted #2e2440; padding-bottom: 5px; }
.gate-summary span { color: #917fa6; }
.gate-summary b { font-weight: 400; color: var(--ink); }
.enter-loop { width: 100%; margin-top: 14px; }

/* ── Echo ──────────────────────────────────────────────────────────────── */
.echo-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.echo-intro { padding: 16px; border: 1px solid #4a3a63; background: radial-gradient(circle at 50% 0%, rgba(176,123,255,.12), transparent 65%), rgba(8,5,13,.45); text-align: center; }
.echo-crystal { width: 70px; height: 90px; margin: 4px auto 12px; background: linear-gradient(180deg, #e2c7ff, #b07bff 32%, #4a2a80 75%, #1a1030); clip-path: polygon(50% 0, 86% 22%, 100% 62%, 72% 100%, 28% 100%, 0 62%, 14% 22%); box-shadow: 0 0 40px rgba(176,123,255,.3); }
.echo-intro h3 { margin: 0 0 6px; font-family: var(--font-head); font-size: 11px; color: var(--violet); font-weight: 400; }
.echo-intro p { margin: 0; color: #a293b4; font-size: 18px; line-height: 1.2; }
.echo-list { display: flex; flex-direction: column; gap: 8px; }
.echo-item { display: flex; align-items: center; gap: 9px; padding: 9px; border: 1px solid #322744; background: rgba(8,5,13,.5); }
.echo-glyph { width: 38px; height: 38px; display: grid; place-items: center; font-family: var(--font-head); font-size: 8px; color: var(--ec); border: 1px solid var(--ec); background: rgba(0,0,0,.3); }
.echo-info { flex: 1; }
.echo-info b { display: block; font-size: 19px; font-weight: 400; }
.echo-info small { display: block; font-size: 15px; color: #9183a2; }
.echo-ranks { display: flex; gap: 3px; margin-top: 4px; }
.echo-ranks i { width: 10px; height: 4px; background: #2a2139; }
.echo-ranks i.on { background: var(--ec); box-shadow: 0 0 6px var(--ec); }
.echo-buy { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }

/* ── Loot ──────────────────────────────────────────────────────────────── */
.loot-panel { width: min(1000px, 95vw); background: transparent; border: 0; box-shadow: none; }
.loot-panel::before, .loot-panel::after { display: none; }
.loot-head { text-align: center; margin-bottom: 18px; }
.loot-head .kicker { font-family: var(--font-head); font-size: 7px; letter-spacing: 2px; color: var(--gold); }
.loot-head h2 { margin: 9px 0 5px; font-family: var(--font-head); font-size: clamp(17px, 2.5vw, 27px); letter-spacing: 2px; color: var(--ink); font-weight: 400; text-shadow: 0 4px 0 #0a0610, 0 0 30px rgba(240,192,90,.18); }
.loot-head p { margin: 0; font-size: 19px; color: #a293b4; }
.loot-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.loot-card {
  position: relative; display: flex; flex-direction: column; min-height: 340px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--lc) 10%, #171020), #0d0915 62%);
  border: 2px solid var(--lc, #4a3a63); box-shadow: 0 0 0 3px #08050c, 0 12px 40px rgba(0,0,0,.5), inset 0 0 50px color-mix(in srgb, var(--lc) 5%, transparent);
  cursor: pointer; transition: transform .12s, box-shadow .12s; animation: lootIn .4s cubic-bezier(.2,.9,.3,1);
  overflow: hidden;
}
.loot-card:nth-child(2) { animation-delay: .07s; }
.loot-card:nth-child(3) { animation-delay: .14s; }
.loot-card:hover { transform: translateY(-6px); box-shadow: 0 0 0 3px #08050c, 0 22px 60px rgba(0,0,0,.6), 0 0 40px color-mix(in srgb, var(--lc) 22%, transparent); }
.loot-card::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--lc) 16%, transparent), transparent 55%); pointer-events: none; }
.loot-rarity { text-align: center; padding-top: 13px; font-family: var(--font-head); font-size: 7px; letter-spacing: 1.4px; color: var(--lc); }
.loot-ico { display: grid; place-items: center; height: 100px; position: relative; }
.loot-ico img { width: 76px; height: 76px; filter: drop-shadow(0 6px 10px rgba(0,0,0,.45)); }
.loot-ico .rune-badge { width: 62px; height: 62px; display: grid; place-items: center; font-family: var(--font-head); font-size: 15px; color: var(--lc); border: 2px solid var(--lc); background: rgba(0,0,0,.4); box-shadow: inset 0 0 22px color-mix(in srgb, var(--lc) 20%, transparent), 0 0 24px color-mix(in srgb, var(--lc) 18%, transparent); transform: rotate(45deg); }
.loot-ico .rune-badge span { transform: rotate(-45deg); }
.loot-ico .sup-icon { width: 52px; height: 52px; }
.loot-body { padding: 0 14px; text-align: center; }
.loot-body h3 { margin: 0; font-size: 23px; font-weight: 400; line-height: 1.05; color: var(--ink); }
.loot-body .loot-type { margin-top: 5px; font-family: var(--font-head); font-size: 6px; letter-spacing: 1px; color: #9586a8; }
.loot-desc { margin: 10px auto 0; font-size: 17px; line-height: 1.18; color: #b7a9c6; min-height: 40px; }
.loot-stats { display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; margin-top: 9px; font-family: var(--font-head); font-size: 6px; color: #a696b8; }
.loot-compare { margin-top: 7px; font-family: var(--font-head); font-size: 6px; }
.loot-take { margin-top: auto; padding: 13px 10px 11px; border-top: 1px solid color-mix(in srgb, var(--lc) 22%, transparent); font-family: var(--font-head); font-size: 8px; letter-spacing: 1px; color: var(--lc); background: color-mix(in srgb, var(--lc) 8%, transparent); }
.loot-take small { display: block; margin-top: 3px; font-family: var(--font-body); font-size: 15px; letter-spacing: 0; color: #9183a2; }
.loot-foot { display: flex; justify-content: center; align-items: center; gap: 10px; margin-top: 16px; flex-wrap: wrap; }
.loot-foot .hint { font-family: var(--font-head); font-size: 6px; color: #7d6f90; }

/* ── Path ──────────────────────────────────────────────────────────────── */
.path-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; }
.path-card { position: relative; padding: 18px 14px; text-align: center; background: linear-gradient(180deg, color-mix(in srgb, var(--pc) 9%, #151020), #0c0812); border: 1px solid var(--pc); cursor: pointer; transition: .12s; }
.path-card:hover { transform: translateY(-4px); box-shadow: 0 14px 40px rgba(0,0,0,.45), 0 0 26px color-mix(in srgb, var(--pc) 14%, transparent); }
.path-glyph { width: 54px; height: 54px; margin: 0 auto 12px; display: grid; place-items: center; font-family: var(--font-head); font-size: 13px; color: var(--pc); border: 1px solid var(--pc); background: rgba(0,0,0,.35); box-shadow: inset 0 0 22px color-mix(in srgb, var(--pc) 14%, transparent); transform: rotate(45deg); }
.path-glyph span { transform: rotate(-45deg); }
.path-card h3 { margin: 0 0 5px; font-family: var(--font-head); font-size: 9px; letter-spacing: .5px; color: var(--pc); font-weight: 400; }
.path-card p { margin: 0; font-size: 17px; line-height: 1.15; color: #a293b4; min-height: 38px; }
.path-meta { display: flex; justify-content: center; gap: 6px; margin-top: 10px; flex-wrap: wrap; }
.path-cta { margin-top: 14px; font-family: var(--font-head); font-size: 7px; color: var(--ink); }

/* ── Shrine ────────────────────────────────────────────────────────────── */
.shrine-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.shrine-card { padding: 20px 16px; text-align: center; border: 1px solid var(--sc); background: linear-gradient(180deg, color-mix(in srgb, var(--sc) 9%, #151020), #0c0812); cursor: pointer; transition: .12s; }
.shrine-card:hover { transform: translateY(-4px); box-shadow: 0 0 30px color-mix(in srgb, var(--sc) 14%, transparent); }
.shrine-glyph { font-size: 38px; color: var(--sc); line-height: 1; margin-bottom: 8px; text-shadow: 0 0 20px var(--sc); }
.shrine-card h3 { margin: 0 0 5px; font-family: var(--font-head); font-size: 10px; color: var(--sc); font-weight: 400; }
.shrine-card p { margin: 0; font-size: 18px; color: #a293b4; }

/* ── Victory / game over ───────────────────────────────────────────────── */
.result-panel { width: min(660px, 94vw); }
.result-hero { text-align: center; padding: 24px 22px 14px; }
.result-kicker { font-family: var(--font-head); font-size: 7px; letter-spacing: 2px; color: var(--gold); }
.result-hero h2 { margin: 10px 0 5px; font-family: var(--font-head); font-size: clamp(18px, 3vw, 30px); letter-spacing: 2px; font-weight: 400; color: var(--gold); text-shadow: 0 4px 0 #1a0e06, 0 0 34px rgba(240,192,90,.3); }
.result-hero p { margin: 0; color: #a293b4; font-size: 19px; }
.result-hero.defeat h2 { color: var(--red); text-shadow: 0 4px 0 #1a0609, 0 0 34px rgba(255,60,90,.3); }
.result-hero.defeat .result-kicker { color: var(--red); }
.summary-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 18px; padding: 6px 22px 16px; }
.summary-grid div { display: flex; justify-content: space-between; padding: 5px 0; border-bottom: 1px dotted #2e2440; font-size: 18px; }
.summary-grid span { color: #9183a2; }
.summary-grid b { font-weight: 400; color: var(--ink); }
.result-actions { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; padding: 12px 22px 22px; }
.result-loot { display: flex; align-items: center; gap: 12px; margin: 0 22px 16px; padding: 10px 12px; border: 1px solid #4a3a63; background: rgba(10,7,16,.5); }
.result-loot img { width: 44px; height: 44px; }
.result-loot b { display: block; font-size: 19px; font-weight: 400; }
.result-loot small { display: block; font-size: 15px; color: #9183a2; }
.result-confetti { position: relative; overflow: hidden; }
.result-confetti::before, .result-confetti::after { content: ''; position: absolute; width: 6px; height: 6px; background: var(--gold); transform: rotate(45deg); animation: confetti 2.4s infinite; }
.result-confetti::after { right: 20%; top: 18%; background: var(--violet); animation-delay: .7s; }

/* ── Settings / how-to ─────────────────────────────────────────────────── */
.settings-list { display: flex; flex-direction: column; gap: 8px; }
.setting-row { display: flex; align-items: center; gap: 12px; padding: 10px 12px; border: 1px solid #322744; background: rgba(8,5,13,.45); }
.setting-row .sr-info { flex: 1; }
.setting-row b { display: block; font-size: 20px; font-weight: 400; }
.setting-row small { display: block; font-size: 15px; color: #9183a2; margin-top: 2px; }
.toggle { width: 48px; height: 24px; flex: 0 0 auto; border: 1px solid #4a3a63; background: #0b0812; position: relative; cursor: pointer; }
.toggle::after { content: ''; position: absolute; left: 2px; top: 3px; width: 16px; height: 16px; background: #5a4a72; transition: .14s; }
.toggle.on { border-color: var(--green); background: rgba(140,240,122,.12); }
.toggle.on::after { left: 27px; background: var(--green); box-shadow: 0 0 10px var(--green); }
.howto-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.howto-card { border: 1px solid #322744; padding: 13px; background: rgba(8,5,13,.4); }
.howto-card h3 { margin: 0 0 8px; font-family: var(--font-head); font-size: 8px; color: var(--gold); font-weight: 400; }
.howto-card p, .howto-card li { font-size: 17px; color: #b7a9c6; line-height: 1.18; }
.howto-card ul { margin: 0; padding-left: 18px; }
.control-list { display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; font-size: 17px; align-items: center; }
.control-list kbd { justify-self: start; }
.element-wheel { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 6px; }
.element-chip { display: inline-flex; align-items: center; gap: 4px; padding: 4px 6px; border: 1px solid color-mix(in srgb, var(--ec) 45%, transparent); background: color-mix(in srgb, var(--ec) 8%, transparent); font-family: var(--font-head); font-size: 6px; color: var(--ec); }
.element-chip img { width: 12px; height: 12px; }

/* ── Boss intro ────────────────────────────────────────────────────────── */
.boss-intro {
  position: fixed; inset: 0; z-index: 55; display: grid; place-items: center; pointer-events: none;
  background: radial-gradient(ellipse at 50% 50%, rgba(30,6,10,.2), rgba(3,1,5,.82) 75%);
  animation: fadeIn .3s;
}
.boss-intro-inner { text-align: center; padding: 20px; animation: bossIntro 2.6s cubic-bezier(.2,.9,.3,1); }
.boss-intro-kicker { display: block; font-family: var(--font-head); font-size: 7px; letter-spacing: 3px; color: #b06a78; margin-bottom: 14px; }
.boss-intro b { display: block; font-family: var(--font-head); font-size: clamp(20px, 4.5vw, 42px); letter-spacing: 3px; color: #ffd7dc; text-shadow: 0 4px 0 #2a060c, 0 0 50px rgba(255,50,80,.4); }
.boss-intro em { display: block; margin-top: 8px; font-family: var(--font-head); font-size: clamp(7px, 1vw, 10px); letter-spacing: 1px; color: #c98a96; font-style: normal; }
.boss-intro-line { width: 160px; height: 1px; margin: 16px auto; background: linear-gradient(90deg, transparent, #ff5f6d, transparent); }
.boss-intro p { margin: 0; font-size: 20px; color: #c7a8b0; max-width: 460px; font-style: italic; }

/* ── Toasts / banners / fade / boot ────────────────────────────────────── */
.toasts { position: fixed; top: 16px; left: 50%; transform: translateX(-50%); z-index: 90; display: flex; flex-direction: column; gap: 6px; align-items: center; pointer-events: none; width: min(520px, 92vw); }
.toast {
  padding: 8px 14px; background: rgba(8,5,14,.92); border: 1px solid var(--tc, #6c558e); border-left: 3px solid var(--tc, #6c558e);
  font-family: var(--font-head); font-size: 7px; letter-spacing: .4px; color: var(--tc, var(--ink));
  box-shadow: 0 8px 26px rgba(0,0,0,.5), 0 0 20px color-mix(in srgb, var(--tc, #6c558e) 10%, transparent);
  animation: toastIn .22s ease-out, toastOut .3s ease-in 2.4s forwards;
  text-align: center; max-width: 100%;
}
.fade { position: fixed; inset: 0; z-index: 80; background: #030207; opacity: 0; pointer-events: none; transition: opacity .18s ease; }
.fade.on { opacity: 1; pointer-events: auto; }
.boot {
  position: fixed; inset: 0; z-index: 100; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px;
  background: radial-gradient(ellipse at 50% 45%, #171022, #05040a 70%);
  transition: opacity .4s, visibility .4s;
}
.boot.off { opacity: 0; visibility: hidden; }
.boot-mark { width: 54px; height: 54px; display: grid; place-items: center; font-family: var(--font-head); font-size: 13px; color: #241708; background: linear-gradient(180deg, #ffe08a, #c88b34); clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%); box-shadow: 0 0 40px rgba(240,192,90,.3); }
.boot-title { margin-top: 8px; font-family: var(--font-head); font-size: 16px; letter-spacing: 2px; color: var(--ink); }
.boot-sub { font-family: var(--font-head); font-size: 7px; letter-spacing: 3px; color: var(--gold); }
.boot-track { width: 180px; height: 3px; margin-top: 16px; background: #1a1226; border: 1px solid #332747; overflow: hidden; }
.boot-track i { display: block; width: 40%; height: 100%; background: linear-gradient(90deg, transparent, var(--gold), transparent); animation: boot 1.1s infinite; }
.boot-tip { font-size: 16px; color: #7d6f90; }

/* ── Animations ────────────────────────────────────────────────────────── */
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes panelIn { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes lootIn { from { opacity: 0; transform: translateY(22px) scale(.97); } to { opacity: 1; transform: none; } }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }
@keyframes bannerIn { from { opacity: 0; transform: scale(.9); letter-spacing: 6px; } to { opacity: 1; transform: scale(1); } }
@keyframes promptFloat { 0%,100% { transform: translate(-50%, 0); } 50% { transform: translate(-50%, -4px); } }
@keyframes nodePulse { 0%,100% { box-shadow: inset 0 0 16px rgba(240,192,90,.02); } 50% { box-shadow: inset 0 0 22px rgba(240,192,90,.12), 0 0 14px rgba(240,192,90,.08); } }
@keyframes bossIntro { 0% { opacity: 0; transform: scale(1.08); letter-spacing: 8px; } 18% { opacity: 1; } 78% { opacity: 1; } 100% { opacity: 0; transform: scale(.98); } }
@keyframes boot { from { transform: translateX(-120%); } to { transform: translateX(260%); } }
@keyframes confetti { 0% { transform: translate(0,0) rotate(45deg); opacity: 0; } 20% { opacity: 1; } 100% { transform: translate(60px, 90px) rotate(405deg); opacity: 0; } }
@keyframes floatY { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }

/* ── Responsive ────────────────────────────────────────────────────────── */
@media (max-width: 1000px) {
  .title-content { left: 5vw; }
  .town-status { width: 250px; }
  .gate-layout { grid-template-columns: 1fr; }
  .forge-layout { grid-template-columns: 240px 1fr; }
  .skills-layout { grid-template-columns: 220px 1fr; }
}
@media (max-width: 820px) {
  body { font-size: 18px; }
  .title-content { width: min(560px, 88vw); left: 6vw; top: 46%; transform: translateY(-50%); }
  .title-blurb { margin: 18px 0 22px; }
  .title-tip { display: none; }
  .title-footer-controls { display: none; }
  .brand-mini { min-width: 0; }
  .brand-mini small { display: none; }
  .town-status { top: 70px; width: 224px; }
  .town-quickstats { gap: 8px; }
  .joystick { display: block; }
  .action-cluster { transform: scale(.9); transform-origin: bottom right; }
  .hud-footer .hud-hint { display: none; }
  .boss-wrap { bottom: 190px; width: 78vw; }
  .loot-grid { gap: 8px; }
  .loot-card { min-height: 300px; }
  .loot-ico { height: 80px; }
  .loot-ico img { width: 60px; height: 60px; }
  .loot-body h3 { font-size: 19px; }
  .loot-desc { font-size: 15px; min-height: 34px; }
  .forge-layout, .skills-layout { grid-template-columns: 1fr; }
  .skill-cols { grid-template-columns: 1fr; }
  .skill-node::after { display: none; }
  .howto-grid { grid-template-columns: 1fr; }
  .weapon-detail { grid-template-columns: 100px 1fr; }
  .weapon-detail .wd-icon img { width: 80px; height: 80px; }
}
@media (max-width: 640px) {
  .title-topbar { padding: 14px 16px; }
  .title-mark { font-size: 6px; }
  .title-content { top: 44%; left: 7vw; width: 86vw; }
  .title-kicker { font-size: 6px; margin-bottom: 12px; }
  .title-logo { font-size: clamp(30px, 10vw, 48px); }
  .title-sub { font-size: 7px; letter-spacing: 2px; }
  .title-blurb { font-size: 18px; margin: 14px 0 18px; }
  .title-menu { width: 100%; }
  .btn-xl { min-width: 0; width: 100%; padding: 13px 18px; font-size: 12px; }
  .btn-xl small { font-size: 14px; }
  .title-menu-row { width: 100%; }
  .title-menu-row .btn { flex: 1; }
  .title-chips { display: none; }
  .title-footer { left: 16px; right: 16px; font-size: 6px; }
  .town-top { padding: 10px 12px; gap: 8px; flex-wrap: wrap; }
  .brand-mini b { font-size: 6px; }
  .brand-rune { width: 28px; height: 28px; font-size: 7px; }
  .res-bar { order: 3; width: 100%; margin-left: 0; justify-content: space-between; gap: 3px; }
  .res-pill { min-width: 0; padding: 4px 5px; font-size: 6px; }
  .res-pill img { width: 12px; height: 12px; }
  .town-status { display: none; }
  .town-dock { bottom: 10px; width: calc(100vw - 12px); padding: 5px; gap: 4px; justify-content: flex-start; }
  .dock-btn { width: 80px; padding: 6px 3px 5px; }
  .dock-glyph { width: 27px; height: 21px; font-size: 6px; }
  .dock-btn b { font-size: 6px; }
  .dock-btn small { display: none; }
  .town-hint { display: none; }
  .interact-prompt { bottom: 100px; font-size: 6px; }
  .hud-top-left { top: 8px; left: 8px; }
  .portrait { width: 38px; height: 38px; }
  .portrait-helm { width: 18px; height: 20px; }
  .portrait-helm::after { left: 15px; top: 19px; }
  .bar { width: 142px; height: 14px; }
  .bar.mp { width: 110px; height: 10px; }
  .bar.xp { width: 142px; }
  .bar b { font-size: 5px; }
  .hud-top-right { top: 8px; right: 8px; gap: 5px; }
  .minimap-box { width: 64px; padding: 3px; }
  #minimap { width: 56px; height: 56px; }
  .mini-meta { display: none; }
  .run-purse span { font-size: 5px; padding: 3px 4px; }
  .run-purse img { width: 10px; height: 10px; }
  .hud-top-right .icon-btn { width: 28px; height: 28px; font-size: 8px; }
  .action-cluster { right: 8px; bottom: 8px; transform: scale(.78); transform-origin: bottom right; }
  .joystick { left: 12px; bottom: 12px; width: 92px; height: 92px; }
  .boss-wrap { bottom: 152px; width: 82vw; }
  .boss-head b { font-size: 6px; }
  .battle-banner { top: 64px; }
  .battle-banner b { font-size: 10px; }
  .battle-banner span { font-size: 5px; }
  .panel { width: 96vw; max-height: 90vh; }
  .panel-head { padding: 12px 12px 10px; }
  .panel-head h2 { font-size: 10px; }
  .panel-head .ph-sub { font-size: 14px; }
  .panel-head .ph-icon { width: 32px; height: 32px; font-size: 7px; }
  .panel-body { padding: 12px; }
  .panel-foot { padding: 10px 12px; }
  .loot-panel { width: 100vw; }
  .loot-grid { grid-template-columns: 1fr; max-height: 62vh; overflow-y: auto; padding: 4px; gap: 7px; }
  .loot-card { min-height: 0; flex-direction: row; align-items: stretch; }
  .loot-rarity { writing-mode: vertical-rl; padding: 8px 2px; font-size: 5px; text-orientation: mixed; }
  .loot-ico { width: 76px; height: auto; min-height: 74px; flex: 0 0 auto; }
  .loot-ico img { width: 46px; height: 46px; }
  .loot-ico .rune-badge { width: 40px; height: 40px; font-size: 10px; }
  .loot-body { text-align: left; padding: 8px 8px 8px 0; flex: 1; min-width: 0; }
  .loot-body h3 { font-size: 18px; }
  .loot-desc { margin: 5px 0 0; font-size: 14px; min-height: 0; }
  .loot-stats { justify-content: flex-start; gap: 6px; margin-top: 5px; font-size: 5px; }
  .loot-compare { font-size: 5px; }
  .loot-take { width: 52px; flex: 0 0 auto; display: grid; place-items: center; padding: 4px; font-size: 6px; border-top: 0; border-left: 1px solid color-mix(in srgb, var(--lc) 24%, transparent); }
  .loot-take small { display: none; }
  .loot-head h2 { font-size: 15px; }
  .loot-head p { font-size: 15px; }
  .path-grid { grid-template-columns: 1fr; }
  .path-card { display: flex; align-items: center; gap: 12px; text-align: left; padding: 10px; }
  .path-glyph { width: 38px; height: 38px; margin: 0; font-size: 9px; flex: 0 0 auto; }
  .path-card p { min-height: 0; }
  .path-cta { margin: 0; }
  .shrine-grid { grid-template-columns: 1fr; }
  .summary-grid { grid-template-columns: 1fr; }
  .weapon-row .wr-actions .btn { padding: 7px 8px; font-size: 6px; }
  .weapon-row .wr-name { font-size: 16px; }
  .gate-biomes { grid-template-columns: 1fr; }
  .echo-layout { grid-template-columns: 1fr; }
  .result-actions .btn { flex: 1; }
  .toasts { top: 8px; }
  .toast { font-size: 6px; }
}
@media (max-height: 520px) and (orientation: landscape) {
  .title-content { top: 50%; transform: translateY(-50%) scale(.82); transform-origin: left center; }
  .title-footer { display: none; }
  .town-status { display: none; }
  .town-dock { bottom: 6px; }
  .boss-wrap { bottom: 64px; }
  .action-cluster { transform: scale(.72); }
  .joystick { width: 84px; height: 84px; }
}
@media (pointer: coarse) {
  .joystick { display: block; }
}

