84:   // ── Stats ──────────────────────────────────────────────────────────────────
85:   deriveStats() {
86:     const m = this.meta;
87:     const w = getWeapon(this.run?.weaponId || m.equippedWeapon) || getWeapon(m.ownedWeapons[0]);
88:     const skills = m.skills || {};
89:     const passives = new Set(Object.keys(skills).filter(k => skills[k] && SKILL_BY_ID.get(k)?.kind === 'passive'));
90:     const b = this.blessings || {};
91:     const echo = m.echo || {};
92:     const vit = m.stats.vit, dex = m.stats.dex, agi = m.stats.agi, int = m.stats.int;
93:     let maxHp = 100 + vit * 8 + m.level * 5 + (echo.vitality || 0) * 14;
94:     if (passives.has('ironwill')) maxHp += 40;
95:     maxHp = Math.round(maxHp * (1 + (b.maxHp || 0)));
96:     const maxMp = Math.round(40 + int * 3 + m.level * 2 + (passives.has('manaflow') ? 20 : 0));
97:     const crit = 3 + dex * 0.35 + (w?.critBonus || 0) + (w?.affixes?.includes('keen') ? 7 : 0) + (b.crit || 0);
98:     const dodge = Math.min(48, agi * 0.25 + (w?.affixes?.includes('vigilant') ? 5 : 0) + (b.dodge || 0));
99:     const attackSpeed = (passives.has('bloodlust') ? 1.15 : 1) * (1 + (b.attackSpeed || 0)) * (w?.affixes?.includes('fury') ? 1.12 : 1);
100:     let damageBonus = (echo.power || 0) * 0.04 + (passives.has('bloodlust') ? 0.10 : 0) + (b.damage || 0);
101:     let elemental = (passives.has('manaflow') ? 0.15 : 0) + (w?.affixes?.includes('arcane') ? 0.10 : 0) + (b.elemental || 0);
102:     return {
103:       maxHp, maxMp, crit: Math.min(85, crit), dodge,
104:       moveSpeed: 96 * (1 + (echo.haste || 0) * 0.025 + (b.moveSpeed || 0) + (w?.affixes?.includes('swift') ? 0.06 : 0)),
105:       damageBonus, elemental, attackSpeed,
106:       lifesteal: (w?.affixes?.includes('vampiric') ? 0.04 : 0) + (b.lifesteal || 0),
107:       mpRegen: 4 + int * 0.07 + (passives.has('manaflow') ? 3 : 0),
108:       hpRegen: b.regen || 0,
109:       damageReduction: (passives.has('ironwill') ? 0.12 : 0),
110:       dodgeCd: 1.15 * (1 - (b.dodgeCd || 0)),
111:       weapon: w,
112:       powerStat: w?.powerStat || 'str',
113:       taken: this.stats?.taken || 0,
114:     };
115:   }
116:   recompute(keepRatio = true) {
117:     const oldMax = this.stats?.maxHp || 1;
118:     const oldMp = this.stats?.maxMp || 1;
119:     const hpRatio = this.player ? this.player.hp / oldMax : 1;
120:     const mpRatio = this.player ? this.player.mp / oldMp : 1;
121:     this.stats = this.deriveStats();
122:     if (this.player) {
123:       if (keepRatio) { this.player.hp = Math.max(1, this.player.hp + (this.stats.maxHp - oldMax)); this.player.mp = Math.min(this.stats.maxMp, this.player.mp + (this.stats.maxMp - oldMp)); }
124:       this.player.hp = clamp(this.player.hp, 1, this.stats.maxHp);
125:       this.player.mp = clamp(this.player.mp, 0, this.stats.maxMp);
126:     }
127:   }
128:   get equippedWeapon() { return getWeapon(this.run?.weaponId || this.meta.equippedWeapon); }
129:   get potions() { return this.run?.potions || this.meta.potions; }
