131:   // ── Lifecycle ──────────────────────────────────────────────────────────────
132:   start() {
133:     if (this.running) return;
134:     this.running = true;
135:     this.lastFrame = performance.now();
136:     requestAnimationFrame(this.frame.bind(this));
137:   }
138:   frame(now) {
139:     if (!this.running) return;
140:     let dt = Math.min(0.05, (now - this.lastFrame) / 1000);
141:     this.lastFrame = now;
142:     const realDt = dt;
143:     this.time += dt;
144:     if (this.stopTime > 0) { this.stopTime -= realDt; dt *= 0.1; }
145:     if (this.slowmo > 0) { this.slowmo -= realDt; dt *= 0.35; }
146:     if (this.mode === 'title') {
147:       this.updateParticles(dt);
148:       this.ui.syncTitle(this);
149:     } else if (this.mode === 'town') {
150:       if (!this.ui.blocking) this.updateTown(dt);
151:       this.updateParticles(dt);
152:     } else if (this.mode === 'dungeon') {
153:       if (!this.ui.blocking) this.updateDungeon(dt);
