159:     if (this.shake < 0.1) this.shake = 0;
160:     this.render();
161:     this.hudTimer -= realDt;
162:     if (this.hudTimer <= 0 && (this.mode === 'dungeon' || this.mode === 'town')) { this.hudTimer = 0.08; this.ui.updateHUD(this); }
163:     this.input.endFrame();
164:     requestAnimationFrame(this.frame.bind(this));
165:   }
