188:   // ── Town ───────────────────────────────────────────────────────────────────
189:   updateTown(dt) {
190:     const p = this.player;
191:     if (!p) return;
192:     const axis = this.input.getAxis();
193:     const aim = this.input.aimAngle(p.x, p.y);
194:     p.update(dt, axis, aim ?? p.aim, aim !== null);
195:     // clamp to town bounds
196:     const b = TOWN_BOUNDS;
197:     p.x = clamp(p.x, b.x + 8, b.x + b.w - 8);
198:     p.y = clamp(p.y, b.y + 8, b.y + b.h - 8);
199:     const hs = nearestHotspot(p.x, p.y);
200:     this.interactTarget = hs;
201:     this.ui.setTownPrompt(hs);
202:     if (this.input.consume('interact') && hs) this.openTown(hs.id);
203:     if (this.input.tap) {
204:       for (const h of TOWN_HOTSPOTS) {
205:         if (dist(this.input.tap.x, this.input.tap.y, h.x, h.y) < h.r + 18) { this.openTown(h.id); break; }
206:       }
207:     }
208:     if (this.input.consume('pause')) this.ui.showPause(this);
209:   }
