215:   // ── Run setup ──────────────────────────────────────────────────────────────
216:   startRun({ biome, difficulty }) {
217:     this.ui.closeModal();
218:     const diff = DIFFICULTIES[difficulty] || DIFFICULTIES.normal;
219:     const seed = Math.floor(Math.random() * 1e9);
220:     this.difficulty = diff;
221:     this.dungeon = generateDungeon(seed, biome, diff.id, this.meta.level);
222:     this.run = {
223:       biome, difficulty: diff.id, seed, weaponId: this.meta.equippedWeapon,
224:       gold: 0, kills: 0, xp: 0, materials: { iron: 0, essence: 0, crystal: 0 },
225:       potions: { ...this.meta.potions }, startTime: this.time, blessings: {},
226:       roomsCleared: 0, eliteKills: 0, damageDealt: 0, damageTaken: 0,
227:       rerolls: 1, dead: false, revived: false,
228:     };
229:     this.blessings = this.run.blessings;
230:     this.meta.potions = { ...this.run.potions };
231:     this.mode = 'dungeon';
232:     this.ui.showScreen('dungeon');
233:     this.audio.sfx('portal');
234:     this.audio.setTrack('dungeon');
235:     this.depth = 0;
236:     this.stats = this.deriveStats();
237:     this.player = new Player(this, 240, 210);
238:     this.player.hp = this.stats.maxHp;
239:     this.player.mp = this.stats.maxMp;
240:     this.enterRoom(this.dungeon.byId.get(this.dungeon.startId));
241:     this.save();
242:   }
