244:   enterRoom(node) {
245:     const d = this.dungeon;
246:     d.currentNode = node.id;
247:     node.visited = true;
248:     node.seen = true;
249:     for (const id of node.next) d.byId.get(id).seen = true;
250:     this.currentNode = node;
251:     this.room = node.room;
252:     this.depth = node.layer / Math.max(1, d.total - 1);
253:     this.enemies = [];
254:     this.projectiles = [];
255:     this.pickups = [];
256:     this.zones = [];
257:     this.effects = [];
258:     this.texts = [];
259:     this.particles = [];
260:     this.boss = null;
261:     this.chest = null;
262:     this.shrine = null;
263:     this.wave = 0;
264:     this.wavesTotal = 0;
265:     this.roomState = 'intro';
266:     this.introTimer = 0.9;
267:     this.clearDelay = -1;
268:     this.pendingLoot = false;
269:     this.interactTarget = null;
270:     this.cooldowns = {};
271:     this.spinTime = 0;
272:     this.room.cleared = false;
273:     this.player.x = 240; this.player.y = 214;
274:     if (node.type === 'boss') { this.player.y = 222; }
275:     this.player.hp = Math.min(this.stats.maxHp, this.player.hp + this.stats.maxHp * 0.14);
276:     this.player.mp = Math.min(this.stats.maxMp, this.player.mp + this.stats.maxMp * 0.25);
277:     this.player.invuln = 0.8;
278:     this.ui.hideBoss();
279:     this.ui.banner(roomLabel(node.type).name, `ROOM ${node.layer + 1} / ${d.total}`, BIOMES[this.run.biome].palette.accent);
280:     this.audio.setTrack('dungeon');
281:     this.save();
282:     if (node.type === 'boss') {
283:       this.spawnBoss();
284:     } else if (node.type === 'start') {
285:       // safe room: pick a path
286:       this.roomState = 'cleared';
287:       this.room.cleared = true;
288:       this.timers.push({ t: 1.0, fn: () => this.openPath() });
289:     } else if (node.type === 'treasure') {
290:       this.chest = { x: 240, y: 146, opened: false };
291:     } else if (node.type === 'shrine') {
292:       this.shrine = { x: 240, y: 150, used: false };
293:     } else {
294:       this.wavesTotal = node.type === 'elite' ? 1 : 2 + (this.depth > 0.55 ? 1 : 0);
295:       this.roomState = 'intro';
296:     }
297:   }
298: 
299:   spawnBoss() {
300:     const def = BOSSES[BIOMES[this.run.biome].boss];
301:     this.boss = new Boss(this, def.id, 240, 104);
302:     this.roomState = 'bossintro';
303:     this.bossIntroTimer = 2.0;
304:     this.player.invuln = 2.5;
305:     this.ui.showBossIntro(def);
306:     this.audio.sfx('bossroar');
307:     this.audio.setTrack('boss');
308:     this.addParticles(240, 104, def.accent, 24, 135, 1);
309:     this.screenShake(8);
310:   }
311: 
312:   spawnWave() {
313:     if (!this.run) return;
314:     this.wave++;
315:     const count = clamp(2 + Math.floor(this.depth * 3.4) + DIFF_INDEX[this.run.difficulty] + (this.wave - 1), 2, 8);
316:     const biome = BIOMES[this.run.biome];
317:     const pool = this.room.roomType === 'elite' ? ['brute', 'wraith', 'mage', 'charger'] : ['husk', 'bat', 'archer', 'charger', 'bomber', 'mage', 'wraith', 'brute'];
318:     const points = shuffle(Math.random, this.room.spawnPoints);
319:     const elite = this.room.roomType === 'elite' && this.wave === 1;
320:     for (let i = 0; i < count; i++) {
321:       const kind = pick(Math.random, pool);
322:       const pt = points[i % points.length];
323:       const e = new Enemy(this, kind, pt.x, pt.y, { element: pick(Math.random, biome.elements), depth: this.depth, elite: elite && i === 0 });
324:       if (elite) e.element = biome.elements[0];
325:       if (dist(e.x, e.y, this.player.x, this.player.y) < 55) { e.x = 60 + Math.random() * 360; e.y = 60 + Math.random() * 150; }
326:       this.enemies.push(e);
327:       this.spawnBurst(e.x, e.y, ELEMENTS[e.element].color, 7, 60);
328:     }
329:     this.roomState = 'fight';
330:     if (this.wavesTotal > 1) this.ui.banner(`WAVE ${this.wave} / ${this.wavesTotal}`, this.room.roomType === 'elite' ? 'ELITE CHAMPION' : 'CLEAR THE CHAMBER', '#ff9b6a');
331:     else this.ui.banner('ELITE CHAMPION', 'CLEAR THE CHAMBER', '#ffb340');
332:     this.audio.sfx('portal', 0.6);
333:   }
334: 
335:   openPath() {
336:     if (!this.dungeon) return;
337:     const node = this.currentNode;
338:     const options = node.next.map(id => {
339:       const n = this.dungeon.byId.get(id);
340:       return { id: n.id, type: n.type, label: roomLabel(n.type).name, desc: roomLabel(n.type).desc, layer: n.layer + 1, elite: n.type === 'elite', boss: n.type === 'boss', biome: BIOMES[this.run.biome].name };
341:     });
342:     if (!options.length) return;
343:     this.audio.sfx('open');
344:     this.ui.showPath(options, this);
345:   }
346:   choosePath(id) {
347:     this.ui.closeModal();
348:     const n = this.dungeon.byId.get(id);
349:     if (!n) return;
350:     this.audio.sfx('portal');
351:     this.fadeTransition(() => this.enterRoom(n));
352:   }
353:   fadeTransition(fn) {
354:     this.ui.fade(0.18, () => { fn(); this.ui.fadeOut(0.2); });
355:   }
356: 
357:   // ── Dungeon update ─────────────────────────────────────────────────────────
358:   updateDungeon(dt) {
359:     const p = this.player;
360:     if (!p) return;
361:     // timers
362:     for (const timer of this.timers) { timer.t -= dt; }
363:     const ready = this.timers.filter(t => t.t <= 0);
364:     this.timers = this.timers.filter(t => t.t > 0);
365:     for (const t of ready) t.fn();
366:     // cooldowns
367:     for (const k of Object.keys(this.cooldowns)) this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt);
368:     // input
369:     const axis = this.input.getAxis();
370:     const aimMouse = this.input.aimAngle(p.x, p.y);
371:     let aim = p.aim;
372:     if (aimMouse !== null && !this.ui.blocking) { aim = aimMouse; p.aim = aim; }
373:     if (this.input.tap) p.aim = Math.atan2(this.input.tap.y - p.y, this.input.tap.x - p.x);
374:     p.update(dt, axis, aim, aimMouse !== null || !!this.input.tap);
375:     if (this.roomState === 'fight' || this.roomState === 'cleared' || this.roomState === 'bossintro') {
376:       if (this.input.consume('attack') || this.input.isHeld('attack')) this.tryAttack();
377:     }
378:     if (this.input.consume('dodge')) p.tryDodge(axis, p.aim);
379:     if (this.input.consume('skill1')) this.useSkill(0);
380:     if (this.input.consume('skill2')) this.useSkill(1);
381:     if (this.input.consume('potion_hp')) this.usePotion('hp');
382:     if (this.input.consume('potion_mp')) this.usePotion('mp');
383:     if (this.input.consume('pause')) this.ui.showPause(this);
384:     if (this.input.consume('interact')) this.tryInteract();
385:     if (this.input.tap && this.roomState === 'cleared') {
386:       if (this.chest && !this.chest.opened && dist(this.input.tap.x, this.input.tap.y, this.chest.x, this.chest.y) < 30) this.tryInteract();
387:       if (this.shrine && !this.shrine.used && dist(this.input.tap.x, this.input.tap.y, this.shrine.x, this.shrine.y) < 30) this.tryInteract();
388:     }
389:     // spin ultimate
390:     if (this.spinTime > 0) {
391:       this.spinTime -= dt;
392:       this.spinTick = (this.spinTick || 0) - dt;
393:       if (this.spinTick <= 0) { this.spinTick = 0.14; this.hitArea(p.x, p.y, 78, this.attackBase() * 0.45, { element: this.equippedWeapon?.element || 'fire', noKnock: true }); this.addParticles(p.x, p.y, '#ffd27a', 3, 100, 0.3); }
394:     }
395:     // room intro
396:     if (this.roomState === 'intro') {
397:       this.introTimer -= dt;
398:       if (this.introTimer <= 0) {
399:         if (this.currentNode.type === 'treasure' || this.currentNode.type === 'shrine') { this.roomState = 'cleared'; this.room.cleared = true; this.ui.banner('INTERACT', 'Press F or tap', '#ffd86b'); }
400:         else { this.roomState = 'fight'; this.spawnWave(); }
401:       }
402:     }
403:     if (this.roomState === 'bossintro') {
404:       this.bossIntroTimer -= dt;
405:       if (this.bossIntroTimer <= 0) this.roomState = 'fight';
406:     }
407:     // enemies
408:     for (const e of this.enemies) e.update(dt);
409:     const before = this.enemies.length;
410:     this.enemies = this.enemies.filter(e => !(e.dead && e.deathTime > 0.9));
411:     // projectiles
412:     for (const pr of this.projectiles) pr.update(dt);
413:     this.projectiles = this.projectiles.filter(pr => !pr.dead);
414:     // pickups
415:     for (const pk of this.pickups) pk.update(dt, p);
416:     this.pickups = this.pickups.filter(pk => !pk.dead);
417:     // zones
418:     for (const z of this.zones) {
419:       z.timer -= dt;
420:       if (!z.exploded && z.timer <= 0) {
421:         z.exploded = true;
422:         z.flash = 0.25;
423:         this.explosion(z.x, z.y, z.r, z.dmg, z.element || 'fire', null, 'enemy', z.kind);
424:         this.screenShake(3);
425:       }
426:       if (z.flash > 0) z.flash -= dt;
427:     }
428:     this.zones = this.zones.filter(z => z.timer > -0.35);
429:     // boss
430:     if (this.boss && !this.boss.dead) {
431:       if (this.roomState === 'fight') this.boss.update(dt);
432:       if (this.boss && this.boss.dead) { /* handled */ }
433:     } else if (this.boss && this.boss.dead) {
434:       this.boss.deathTime += dt;
435:     }
436:     // effects
437:     for (const fx of this.effects) fx.life -= dt;
438:     this.effects = this.effects.filter(fx => fx.life > 0);
439:     this.updateParticles(dt);
440:     // wave clear
441:     if (this.roomState === 'fight' && this.boss === null) {
442:       const alive = this.enemies.some(e => !e.dead);
443:       if (!alive && this.wave < this.wavesTotal) {
444:         if (this.clearDelay < 0) this.clearDelay = 0.9;
445:         this.clearDelay -= dt;
446:         if (this.clearDelay <= 0) { this.clearDelay = -1; this.spawnWave(); }
447:       } else if (!alive && this.wave >= this.wavesTotal) {
448:         if (this.clearDelay < 0) this.clearDelay = 1.0;
449:         this.clearDelay -= dt;
450:         if (this.clearDelay <= 0) { this.clearDelay = -1; this.clearRoom(); }
451:       }
452:     }
453:     // boss clear check
454:     if (this.roomState === 'fight' && this.boss && this.boss.dead && this.boss.deathTime > 1.8) {
455:       this.roomState = 'cleared';
456:     }
457:   }
