516:   // ── Combat ─────────────────────────────────────────────────────────────────
517:   attackBase(weapon = this.equippedWeapon) {
518:     if (!weapon) return 5;
519:     const power = this.meta.stats[weapon.powerStat] || 5;
520:     const upgrade = 1 + (this.meta.upgrades?.[weapon.id] || 0) * 0.08;
521:     const base = (weapon.baseDmg * upgrade) / weapon.rarityMult;
522:     let dmg = base * (1 + power / 100) * weapon.rarityMult * (1 + this.stats.damageBonus);
523:     if (this.stats.elemental) dmg *= (1 + this.stats.elemental);
524:     if (weapon.affixes?.includes('umbral') && this.player.hp / this.stats.maxHp < 0.35) dmg *= 1.2;
525:     return dmg;
526:   }
527:   tryAttack() {
528:     const p = this.player, w = this.equippedWeapon;
529:     if (!w || p.dead || p.attackCd > 0) return;
530:     const speed = w.speed * this.stats.attackSpeed;
531:     p.attackCd = 1 / Math.max(0.25, speed);
532:     p.attackAnim = 0.2;
533:     const crit = Math.random() * 100 < this.stats.crit;
534:     const base = this.attackBase(w);
535:     if (w.kind === 'melee') {
536:       const range = w.range;
537:       const aim = p.aim;
538:       this.effects.push({ type: 'slash', x: p.x, y: p.y - 8, angle: aim, range, arc: w.arc, life: 0.2, maxLife: 0.2, color: ELEMENTS[w.element].light });
539:       let hitAny = false;
540:       const targets = [...this.enemies.filter(e => !e.dead), this.boss && !this.boss.dead ? this.boss : null].filter(Boolean);
541:       for (const e of targets) {
542:         const d = dist(p.x, p.y, e.x, e.y);
543:         if (d > range + e.r) continue;
544:         const a = angleTo(p.x, p.y, e.x, e.y);
545:         if (Math.abs(angleDiff(a, aim)) > w.arc / 2 && d > e.r + 10) continue;
546:         hitAny = true;
547:         this.damageEnemy(e, base, { element: w.element, crit, source: 'weapon', angle: aim, knock: 32 });
548:         this.applyAffixes(e, w, base, crit);
549:       }
550:       if (hitAny) { this.hitStop(0.035); this.screenShake(w.type === 'axe' ? 3.2 : 1.8); this.audio.sfx(crit ? 'crit' : 'slash'); }
551:       else this.audio.sfx('slash', 0.6);
552:       if (w.type === 'spear') this.effects.push({ type: 'thrust', x: p.x, y: p.y - 8, angle: aim, range, life: 0.15, maxLife: 0.15, color: ELEMENTS[w.element].light });
553:     } else {
554:       const count = w.pellets || 1;
555:       for (let i = 0; i < count; i++) {
556:         const spread = count > 1 ? (i - (count - 1) / 2) * w.spread : 0;
557:         this.spawnProjectile({
558:           x: p.x + Math.cos(p.aim) * 12, y: p.y - 8 + Math.sin(p.aim) * 12,
559:           angle: p.aim + spread + (Math.random() - 0.5) * (w.type === 'gun' ? 0.05 : 0.01),
560:           speed: w.type === 'bow' ? 330 : w.type === 'gun' ? 380 : 240,
561:           dmg: base, team: 'player', kind: w.projectile === 'bullet' ? 'bullet' : w.projectile === 'homing' ? 'homing' : w.projectile === 'orb' ? 'orb' : 'arrow',
562:           element: w.element, color: ELEMENTS[w.element].color, radius: w.type === 'staff' ? 6 : 4,
563:           splash: w.splash, crit, life: 1.4, homing: w.projectile === 'homing' ? 2.2 : 0,
564:         });
565:       }
566:       this.audio.sfx(w.type === 'bow' ? 'arrow' : 'shoot');
567:       this.spawnBurst(p.x + Math.cos(p.aim) * 14, p.y - 8 + Math.sin(p.aim) * 14, ELEMENTS[w.element].light, 3, 40, 0.2);
568:       this.screenShake(w.type === 'gun' ? 1.4 : 0.6);
569:     }
570:     this.applyAffixHeal(w);
571:   }
572:   applyAffixes(enemy, w, base, crit) {
573:     if (!enemy || !w.affixes) return;
574:     if (w.affixes.includes('blazing')) { enemy.burn = Math.max(enemy.burn, 2.4); enemy.burnDmg = Math.max(enemy.burnDmg, 3 + base * 0.06); }
575:     if (w.affixes.includes('frostbound')) enemy.slow = Math.max(enemy.slow, 1.6);
576:     if (w.affixes.includes('earthshatter') && Math.random() < 0.12) { enemy.stun = Math.max(enemy.stun, 0.9); this.addText(enemy.x, enemy.y - 34, 'STUN', '#c98b4b'); }
577:     if (w.affixes.includes('thunderous') && Math.random() < 0.2) {
578:       const other = this.nearestEnemy(enemy.x, enemy.y, 100, enemy);
579:       if (other) { this.damageEnemy(other, base * 0.5, { element: 'lightning', crit: false, source: 'chain' }); this.effects.push({ type: 'lightning', x1: enemy.x, y1: enemy.y, x2: other.x, y2: other.y, life: 0.18, maxLife: 0.18, color: '#ffe14d' }); this.audio.sfx('thunder'); }
580:     }
581:   }
582:   applyAffixHeal(w) {
583:     if (w.affixes?.includes('radiant')) this.player.heal(3);
584:   }
585:   useSkill(slot) {
586:     const id = this.meta.equippedSkills?.[slot];
587:     if (!id) { this.ui.toast('No skill equipped. Visit the Skill Shrine.', '#ffb340'); this.audio.sfx('error'); return; }
588:     const skill = SKILL_BY_ID.get(id);
589:     if (!skill || skill.kind !== 'active') return;
590:     if (!this.meta.skills?.[id]) { this.ui.toast('Skill not unlocked.', '#ffb340'); return; }
591:     if ((this.cooldowns[id] || 0) > 0) { this.audio.sfx('error'); return; }
592:     if (this.player.mp < skill.mp) { this.ui.toast('Not enough MP.', '#57b8ff'); this.audio.sfx('error'); return; }
593:     this.player.mp -= skill.mp;
594:     this.cooldowns[id] = skill.cd;
595:     const p = this.player, w = this.equippedWeapon;
596:     const base = this.attackBase();
597:     if (id === 'whirlwind') {
598:       this.effects.push({ type: 'spin', x: p.x, y: p.y, life: 0.55, maxLife: 0.55, color: '#ff9b6a' });
599:       for (let i = 0; i < 3; i++) this.timers.push({ t: 0.05 + i * 0.16, fn: () => { this.hitArea(p.x, p.y, 78, base * 0.8, { element: w?.element || 'fire', crit: Math.random() * 100 < this.stats.crit }); this.screenShake(2.5); } });
600:       this.audio.sfx('slash');
601:     } else if (id === 'bladestorm') {
602:       this.spinTime = 1.8; this.spinTick = 0;
603:       this.effects.push({ type: 'spin', x: p.x, y: p.y, life: 1.8, maxLife: 1.8, color: '#ffd27a' });
604:       this.audio.sfx('slash');
605:     } else if (id === 'shieldbash') {
606:       const aim = p.aim;
607:       for (const e of [...this.enemies, this.boss].filter(Boolean)) {
608:         if (e.dead) continue;
609:         const d = dist(p.x, p.y, e.x, e.y);
610:         if (d < 100 && Math.abs(angleDiff(angleTo(p.x, p.y, e.x, e.y), aim)) < 0.85) {
611:           this.damageEnemy(e, base * 1.35, { element: 'light', crit: false, source: 'skill', angle: aim, knock: 180 });
612:           if (!e.isBoss) e.stun = Math.max(e.stun, 1.0);
613:         }
614:       }
615:       this.effects.push({ type: 'cone', x: p.x, y: p.y - 8, angle: aim, range: 100, life: 0.3, maxLife: 0.3, color: '#6db8ff' });
616:       this.screenShake(5); this.audio.sfx('shield');
617:       this.player.shieldTimer = Math.max(this.player.shieldTimer, 2.5);
618:     } else if (id === 'aegis') {
619:       this.player.shield = Math.round(this.stats.maxHp * 0.45 + 30);
620:       this.player.shieldTimer = 6;
621:       this.addText(p.x, p.y - 34, 'AEGIS', '#6db8ff', 1.3);
622:       this.audio.sfx('shield');
623:     } else if (id === 'fireball') {
624:       this.spawnProjectile({ x: p.x + Math.cos(p.aim) * 14, y: p.y - 8 + Math.sin(p.aim) * 14, angle: p.aim, speed: 210, dmg: base * 1.7, team: 'player', kind: 'fireball', element: 'fire', color: '#ff7b3a', radius: 8, splash: 44, crit: Math.random() * 100 < this.stats.crit, life: 1.6 });
625:       this.audio.sfx('shoot');
626:     } else if (id === 'starfall') {
627:       for (let i = 0; i < 5; i++) {
628:         const target = i < 2 && this.nearestEnemy(p.x, p.y, 300) ? this.nearestEnemy(p.x, p.y, 300) : null;
629:         const x = target ? target.x + (Math.random() - 0.5) * 40 : p.x + (Math.random() - 0.5) * 180;
630:         const y = target ? target.y + (Math.random() - 0.5) * 40 : p.y + (Math.random() - 0.5) * 140;
631:         this.addZone({ x: clamp(x, 50, 430), y: clamp(y, 50, 220), r: 32, delay: 0.55 + i * 0.12, duration: 0.25, color: '#c78cff', dmg: base * 1.2, element: 'light', kind: 'meteor', team: 'player' });
632:       }
633:       this.audio.sfx('thunder');
634:     }
635:     this.ui.toast(`${skill.name}`, skill.color);
636:   }
