639:     if (!run) return;
640:     if ((run.potions[type] || 0) <= 0) { this.audio.sfx('error'); this.ui.toast(`No ${type === 'hp' ? 'health' : 'mana'} flasks left.`, '#ffb340'); return; }
641:     run.potions[type]--;
642:     if (type === 'hp') { this.player.heal(this.stats.maxHp * 0.4); }
643:     else { this.player.mp = Math.min(this.stats.maxMp, this.player.mp + this.stats.maxMp * 0.55); this.addText(this.player.x, this.player.y - 26, '+MP', '#57b8ff'); }
644:     this.audio.sfx('potion');
