648:   hitArea(x, y, r, dmg, opts = {}) {
649:     const targets = [...this.enemies.filter(e => !e.dead), this.boss && !this.boss.dead ? this.boss : null].filter(Boolean);
650:     for (const e of targets) {
651:       if (dist(x, y, e.x, e.y) < r + e.r) this.damageEnemy(e, dmg, { element: opts.element || 'fire', crit: opts.crit || false, source: 'skill', knock: opts.knock, noKnock: opts.noKnock });
652:     }
653:   }
654: 
655:   damageEnemy(enemy, amount, opts = {}) {
656:     if (!enemy || enemy.dead) return 0;
657:     const mult = elementMultiplier(opts.element || 'light', enemy.element);
658:     const crit = opts.crit && !opts.noCrit;
659:     let dmg = amount * mult * (crit ? 1.9 : 1);
660:     if (enemy.isBoss && enemy.invuln > 0) return 0;
661:     dmg = Math.max(1, Math.round(dmg));
662:     enemy.hp -= dmg;
663:     enemy.hitFlash = 0.12;
664:     this.run && (this.run.damageDealt += dmg);
665:     if (opts.knock && !enemy.isBoss && !opts.noKnock) {
666:       const a = opts.angle ?? angleTo(this.player.x, this.player.y, enemy.x, enemy.y);
667:       enemy.knock.x += Math.cos(a) * opts.knock;
668:       enemy.knock.y += Math.sin(a) * opts.knock;
669:     }
670:     if (opts.stunChance && Math.random() < opts.stunChance) enemy.stun = Math.max(enemy.stun, 0.7);
671:     if (this.stats.lifesteal > 0 && !opts.dot) this.player.heal(dmg * this.stats.lifesteal);
672:     // visual feedback
673:     const col = crit ? '#ffd86b' : mult > 1 ? ELEMENTS[opts.element].light : mult < 1 ? '#8a84a8' : '#f0e6d2';
674:     this.addText(enemy.x + (Math.random() - 0.5) * 8, enemy.y - (enemy.isBoss ? 52 : enemy.size[1] * 0.8) - 6, String(dmg), col, crit ? 1.45 : 1);
675:     if (mult > 1 && Math.random() < 0.6) this.addText(enemy.x, enemy.y - 30, 'WEAK!', ELEMENTS[opts.element].light, 0.9, 0.6);
676:     if (!opts.silent) {
677:       this.audio.sfx(crit ? 'crit' : 'hit', 0.7);
678:       this.spawnBurst(enemy.x, enemy.y - 8, ELEMENTS[opts.element].color, crit ? 9 : 5, crit ? 110 : 70, 0.4);
679:     }
680:     if (enemy.hp <= 0) {
681:       enemy.hp = 0;
682:       if (enemy.isBoss) { if (!enemy.dead) { enemy.dead = true; enemy.deathTime = 0; this.onBossDeath(enemy); } }
683:       else enemy.die();
684:     }
685:     return dmg;
686:   }
687:   damagePlayer(amount, source) { this.player.takeDamage(amount, source); }
688: 
689:   nearestEnemy(x, y, max = 9999, exclude = null) {
690:     let best = null, bd = max * max;
691:     for (const e of this.enemies) {
692:       if (e.dead || e === exclude) continue;
693:       const d = dist2(x, y, e.x, e.y); if (d < bd) { bd = d; best = e; }
694:     }
695:     if (this.boss && !this.boss.dead && this.boss !== exclude) { const d = dist2(x, y, this.boss.x, this.boss.y); if (d < bd) best = this.boss; }
696:     return best;
697:   }
