700:     const pr = new Projectile({ ...opts, game: this });
701:     pr.game = this;
702:     this.projectiles.push(pr);
703:     return pr;
704:   }
705:   projectileHit(proj, enemy) {
706:     this.damageEnemy(enemy, proj.dmg, { element: proj.element, crit: proj.crit, source: 'projectile' });
707:     if (proj.splash) this.explosion(proj.x, proj.y, proj.splash, proj.dmg * 0.55, proj.element, null, 'player');
708:     if (proj.crit) this.audio.sfx('crit');
709:   }
710:   explosion(x, y, r, dmg, element, source, team = 'enemy', kind = '') {
711:     this.particles.push(new Particle({ x, y, life: 0.36, maxLife: 0.36, color: ELEMENTS[element]?.light || '#ffd27a', ring: true, radius: 5, growth: r * 3.2, alpha: 0.8 }));
712:     this.addParticles(x, y, ELEMENTS[element]?.color || '#ff7b3a', 12, 140, 0.55);
713:     this.addParticles(x, y, '#fff2c0', 5, 90, 0.3);
714:     this.audio.sfx('explosion', 0.7);
715:     if (team === 'player') {
716:       for (const e of [...this.enemies, this.boss].filter(Boolean)) {
717:         if (e.dead) continue;
718:         if (dist(x, y, e.x, e.y) < r + e.r) this.damageEnemy(e, dmg, { element, crit: false, source: 'explosion' });
719:       }
720:     } else {
721:       if (dist(x, y, this.player.x, this.player.y) < r + this.player.r) this.damagePlayer(dmg, source);
722:     }
723:   }
724:   applyBlessing(b) {
725:     const s = this.run.blessings;
726:     b.apply(s);
727:     this.recompute();
728:     if (s.healNow) { this.player.heal(this.stats.maxHp * s.healNow); s.healNow = 0; }
729:     this.spawnBurst(this.player.x, this.player.y, b.color, 14, 90);
730:     this.save();
731:   }
