744:     this.audio.sfx('death', 0.35);
745:     const gold = e.gold + Math.round(e.gold * (this.blessings.gold || 0));
746:     this.spawnGold(e.x, e.y, gold);
747:     if (e.elite) {
748:       this.addPickup('essence', 1, e.x, e.y);
749:       this.addPickup('crystal', 1, e.x, e.y);
750:       this.run.eliteKills++;
751:       this.meta.gems += 2;
752:     }
753:     if (Math.random() < 0.05) this.addPickup(Math.random() < 0.5 ? 'hp' : 'mp', 1, e.x, e.y);
754:     if (this.equippedWeapon?.affixes?.includes('radiant')) this.player.heal(3);
755:     this.addText(e.x, e.y - 22, `+${e.xp} XP`, '#b478ff', 0.9, 0.7);
