763:     this.addParticles(b.x, b.y, b.def.color, 30, 140, 1.2);
764:     this.run.gold += 80 + Math.round(120 * this.difficulty.reward);
765:     const gemGain = Math.round((12 + Math.floor(Math.random() * 11)) * (1 + (this.meta.echo.fortune || 0) * 0.07)) * (DIFF_INDEX[this.run.difficulty] + 1);
766:     this.meta.gems += gemGain;
767:     const echoGain = 1 + DIFF_INDEX[this.run.difficulty];
768:     this.meta.echoes += echoGain;
769:     this.run._gems = gemGain; this.run._echoes = echoGain;
770:     this.run.materials.crystal += 2;
