139: export function collide(room, x, y, r) {
140:   const b = room.bounds;
141:   let nx = clamp(x, b.x + r, b.x + b.w - r);
142:   let ny = clamp(y, b.y + r, b.y + b.h - r);
143:   for (const p of room.props) {
144:     if (p.shape === 'circle') {
145:       const d = Math.hypot(nx - p.x, ny - p.y);
146:       const min = r + p.r;
147:       if (d < min && d > 0.0001) { nx = p.x + (nx - p.x) / d * min; ny = p.y + (ny - p.y) / d * min; }
148:       else if (d <= 0.0001) nx += min;
149:     } else if (p.shape === 'rect') {
150:       const cx = clamp(nx, p.x, p.x + p.w), cy = clamp(ny, p.y, p.y + p.h);
151:       const dx = nx - cx, dy = ny - cy, d = Math.hypot(dx, dy);
152:       if (d < r) {
153:         if (d > 0.0001) { nx = cx + dx / d * r; ny = cy + dy / d * r; }
154:         else {
155:           const left = nx - p.x, right = p.x + p.w - nx, top = ny - p.y, bot = p.y + p.h - ny;
156:           const m = Math.min(left, right, top, bot);
157:           if (m === left) nx = p.x - r; else if (m === right) nx = p.x + p.w + r; else if (m === top) ny = p.y - r; else ny = p.y + p.h + r;
158:         }
159:       }
160:     }
161:   }
162:   nx = clamp(nx, b.x + r, b.x + b.w - r);
163:   ny = clamp(ny, b.y + r, b.y + b.h - r);
164:   return { x: nx, y: ny };
165: }
