const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const wait = (p, ms) => p.waitForTimeout(ms);

(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1',
  });
  const page = await ctx.newPage();
  const logs = [];
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') logs.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', e => logs.push(`[pageerror] ${e.message}\n${e.stack}`));

  const shot = async name => {
    await page.screenshot({ path: `screenshots/${name}.png` });
    console.log('shot', name);
  };
  const ov = async label => {
    const o = await page.evaluate(() => ({
      sw: document.documentElement.scrollWidth, iw: innerWidth,
      sh: document.documentElement.scrollHeight, ih: innerHeight,
    }));
    console.log('overflow', label, JSON.stringify(o), o.sw > o.iw ? 'HORIZONTAL!' : 'ok');
    return o;
  };

  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await wait(page, 1400);
  await shot('m01-title');
  await ov('title');

  await page.tap('#btn-play');
  await wait(page, 900);
  await shot('m02-town');
  await ov('town');

  for (const id of ['gate', 'forge', 'skills', 'shop', 'codex', 'echo']) {
    const btn = page.locator(`[data-town="${id}"]`);
    if (!(await btn.count())) { console.log('MISSING dock', id); continue; }
    await btn.tap();
    await wait(page, 550);
    await shot(`m03-${id}`);
    await ov(id);
    const close = page.locator('[data-close]').first();
    if (await close.count()) await close.tap();
    await wait(page, 250);
  }

  // Forge upgrade
  await page.tap('[data-town="forge"]');
  await wait(page, 500);
  const before = await page.evaluate(() => {
    const m = window.__SKPA__.game.meta;
    return { upgrades: { ...m.upgrades }, gold: m.gold, iron: m.materials.iron, essence: m.materials.essence };
  });
  await page.locator('[data-upgrade]').first().tap();
  await wait(page, 600);
  const after = await page.evaluate(() => {
    const m = window.__SKPA__.game.meta;
    return { upgrades: { ...m.upgrades }, gold: m.gold, iron: m.materials.iron, essence: m.materials.essence };
  });
  console.log('forge before', JSON.stringify(before));
  console.log('forge after ', JSON.stringify(after));
  await shot('m04-forge-upgrade');
  await page.tap('[data-close]');
  await wait(page, 300);

  // Start a run through real UI
  await page.tap('[data-town="gate"]');
  await wait(page, 500);
  await page.tap('#enter-loop');
  await wait(page, 1500);
  if (await page.locator('[data-path]').count()) {
    await shot('m05-path');
    await page.locator('[data-path]').first().tap();
    await wait(page, 1000);
  }
  await shot('m06-dungeon');
  await ov('dungeon');

  // Joystick drag
  const jb = await page.locator('#joystick').boundingBox();
  console.log('joystick box', JSON.stringify(jb));
  if (jb) {
    await page.mouse.move(jb.x + jb.width / 2, jb.y + jb.height / 2);
    await page.mouse.down();
    await page.mouse.move(jb.x + jb.width / 2 + 30, jb.y + jb.height / 2 - 4, { steps: 6 });
    await wait(page, 900);
    await shot('m07-moving');
    const joy = await page.evaluate(() => {
      const g = window.__SKPA__.game;
      return { x: Math.round(g.player.x), y: Math.round(g.player.y), mode: g.mode };
    });
    console.log('after joystick', JSON.stringify(joy));
    await page.mouse.up();
  }

  // Action buttons
  for (const id of ['btn-attack', 'btn-skill1', 'btn-dodge']) {
    const b = page.locator('#' + id);
    if (await b.count()) { await b.tap(); await wait(page, 160); }
  }
  await shot('m08-action');

  // Pause + settings + resume
  await page.tap('#btn-pause');
  await wait(page, 450);
  await shot('m09-pause');
  await ov('pause');
  if (await page.locator('[data-act="settings"]').count()) {
    await page.tap('[data-act="settings"]');
    await wait(page, 450);
    await shot('m10-settings');
    await page.locator('[data-close]').first().tap();
    await wait(page, 300);
  }
  if (await page.locator('[data-act="resume"]').count()) {
    await page.tap('[data-act="resume"]');
    await wait(page, 350);
  }

  // Loot modal
  await page.evaluate(() => { const g = window.__SKPA__.game; g.pendingLoot = false; g.offerLoot(true); });
  await wait(page, 650);
  await shot('m11-loot');
  await ov('loot');
  const reroll = await page.evaluate(() => {
    const el = document.getElementById('loot-reroll');
    return el ? { disabled: el.disabled, text: el.textContent } : null;
  });
  console.log('loot reroll', JSON.stringify(reroll));

  // Choose the first card to close
  if (await page.locator('[data-loot]').count()) {
    await page.locator('[data-loot]').first().tap();
    await wait(page, 800);
  }

  // Game over with enough gems to revive
  await page.evaluate(() => {
    const g = window.__SKPA__.game;
    g.meta.gems = 45;
    g.onPlayerDeath();
  });
  await wait(page, 650);
  await shot('m12-gameover');
  await ov('gameover');
  const reviveBtn = page.locator('[data-act="revive"]');
  console.log('revive buttons', await reviveBtn.count());
  if (await reviveBtn.count()) {
    await reviveBtn.tap();
    await wait(page, 800);
    const st = await page.evaluate(() => {
      const g = window.__SKPA__.game;
      return { mode: g.mode, hp: Math.round(g.player.hp), gems: g.meta.gems, revived: g.run.revived };
    });
    console.log('after revive', JSON.stringify(st));
    await shot('m13-revived');
  }

  // Abandon run
  await page.tap('#btn-pause');
  await wait(page, 400);
  if (await page.locator('[data-act="abandon"]').count()) {
    page.once('dialog', d => d.accept());
    await page.locator('[data-act="abandon"]').tap();
    await wait(page, 800);
    await shot('m14-abandoned');
    const st = await page.evaluate(() => ({ mode: window.__SKPA__.game.mode, screen: document.querySelector('.screen.active')?.id }));
    console.log('after abandon', JSON.stringify(st));
  }

  console.log('--- LOGS ---');
  console.log(logs.length ? logs.join('\n') : 'clean');
  await browser.close();
})();

