input.content:
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 844, height: 390 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const page = await ctx.newPage();
  const logs = [];
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') logs.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', e => logs.push(`[pageerror] ${e.message}`));
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: 'screenshots/l01-title.png' });
  await page.tap('#btn-play');
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/l02-town.png' });
  console.log('overflow', await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, iw: innerWidth, sh: document.documentElement.scrollHeight, ih: innerHeight })));
  await page.tap('[data-town="gate"]');
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'screenshots/l03-gate.png' });
  await page.tap('#enter-loop');
  await page.waitForTimeout(1500);
  if (await page.locator('[data-path]').count()) {
    await page.screenshot({ path: 'screenshots/l04-path.png' });
    await page.locator('[data-path]').first().tap();
    await page.waitForTimeout(1000);
  }
  await page.screenshot({ path: 'screenshots/l05-dungeon.png' });
  console.log('boxes', await page.evaluate(() => {
    const box = id => { const r = document.getElementById(id)?.getBoundingClientRect(); return r ? [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)] : null; };
    return { joy: box('joystick'), atk: box('btn-attack'), dash: box('btn-dodge'), minimap: box('minimap'), canvas: box('game') };
  }));
  console.log('--- LOGS ---');
  console.log(logs.length ? logs.join('\n') : 'clean');
  await browser.close();
})();

