const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = (p, ms) => p.waitForTimeout(ms);
(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const logs = [];
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') logs.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', e => logs.push(`[pageerror] ${e.message}\n${e.stack}`));
  const state = () => page.evaluate(() => {
    const m = window.__SKPA__.game.meta;
    return { gold: m.gold, gems: m.gems, echoes: m.echoes, hpPotions: m.potions.hp, mpPotions: m.potions.mp, skillPoints: m.skillPoints, statPoints: m.statPoints, skills: Object.keys(m.skills || {}), equippedSkills: m.equippedSkills, weapon: m.equippedWeapon, autoEquip: m.settings.autoEquip };
  });
  const shot = n => page.screenshot({ path: `screenshots/${n}.png` });

  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await wait(page, 1100);
  await page.click('#btn-play');
  await wait(page, 800);

  // ── Shop ──
  await page.click('[data-town="shop"]');
  await wait(page, 400);
  const beforeShop = await state();
  await page.locator('[data-buy="potion_hp"]').click();
  await wait(page, 450);
  const afterShop = await state();
  console.log('SHOP', JSON.stringify({ beforeShop, afterShop }));
  await shot('f01-shop-bought');
  await page.locator('.panel-close').first().click();
  await wait(page, 250);

  // ── Skills: unlock + equip ──
  await page.click('[data-town="skills"]');
  await wait(page, 450);
  const beforeSkill = await state();
  const unlock = page.locator('[data-unlock]:not([disabled])').first();
  console.log('unlock available', await unlock.count(), await unlock.count() ? await unlock.textContent() : '');
  if (await unlock.count()) { await unlock.click(); await wait(page, 500); }
  const afterUnlock = await state();
  console.log('SKILL UNLOCK', JSON.stringify({ beforeSkill, afterUnlock }));
  await shot('f02-skills-unlocked');
  // Equip the newly unlocked active skill to empty slot if possible
  const slot = page.locator('[data-slot]').first();
  if (await slot.count()) { await slot.click(); await wait(page, 450); }
  const afterEquip = await state();
  console.log('SKILL EQUIP', JSON.stringify(afterEquip));
  await shot('f03-skills-equipped');
  await page.locator('.panel-close').first().click();
  await wait(page, 250);

  // ── Codex detail ──
  await page.click('[data-town="codex"]');
  await wait(page, 450);
  await page.locator('[data-weapon]').first().click();
  await wait(page, 450);
  await shot('f04-codex-detail');
  console.log('codex detail open', await page.locator('#codex-back').count());
  await page.locator('#codex-back').click();
  await wait(page, 350);
  await page.locator('.panel-close').first().click();
  await wait(page, 250);

  // ── Echo purchase ──
  await page.evaluate(() => { window.__SKPA__.game.meta.echoes = 12; window.__SKPA__.game.save(); });
  await page.click('[data-town="echo"]');
  await wait(page, 450);
  const beforeEcho = await state();
  const echoBtn = page.locator('[data-echo]:not([disabled])').first();
  console.log('echo btn', await echoBtn.count(), await echoBtn.count() ? await echoBtn.textContent() : '');
  if (await echoBtn.count()) { await echoBtn.click(); await wait(page, 500); }
  const afterEcho = await state();
  console.log('ECHO', JSON.stringify({ beforeEcho, afterEcho }));
  await shot('f05-echo-bought');
  await page.locator('.panel-close').first().click();
  await wait(page, 250);

  // ── Forge auto-equip toggle ──
  await page.click('[data-town="forge"]');
  await wait(page, 450);
  const ae1 = await state();
  await page.click('#toggle-autoequip');
  await wait(page, 350);
  const ae2 = await state();
  await page.click('#toggle-autoequip');
  await wait(page, 350);
  const ae3 = await state();
  console.log('AUTO-EQUIP', JSON.stringify({ ae1: ae1.autoEquip, ae2: ae2.autoEquip, ae3: ae3.autoEquip }));
  await page.locator('.panel-close').first().click();
  await wait(page, 250);

  // ── Run + loot reroll ──
  await page.evaluate(() => { window.__SKPA__.game.meta.gems = 25; });
  await page.click('[data-town="gate"]');
  await wait(page, 400);
  await page.click('#enter-loop');
  await wait(page, 1500);
  if (await page.locator('[data-path]').count()) {
    await page.locator('[data-path]').first().click();
    await wait(page, 1100);
  }
  await page.evaluate(() => { const g = window.__SKPA__.game; g.pendingLoot = false; g.offerLoot(false); });
  await wait(page, 500);
  const rrBefore = await page.evaluate(() => ({ disabled: document.getElementById('loot-reroll').disabled, rerolls: window.__SKPA__.game.run.rerolls, gems: window.__SKPA__.game.meta.gems }));
  const cardsBefore = await page.locator('[data-loot] h3').allTextContents();
  await page.locator('#loot-reroll').click();
  await wait(page, 550);
  const rrAfter = await page.evaluate(() => ({ disabled: document.getElementById('loot-reroll').disabled, rerolls: window.__SKPA__.game.run.rerolls, gems: window.__SKPA__.game.meta.gems }));
  const cardsAfter = await page.locator('[data-loot] h3').allTextContents();
  console.log('LOOT REROLL', JSON.stringify({ rrBefore, rrAfter, cardsBefore, cardsAfter }));
  await shot('f06-loot-reroll');
  // Choose a card
  if (await page.locator('[data-loot]').count()) { await page.locator('[data-loot]').first().click(); await wait(page, 900); }

  // ── Pause settings toggles ──
  await page.click('#btn-pause');
  await wait(page, 400);
  await page.locator('[data-act="settings"]').click();
  await wait(page, 400);
  const musicBefore = await page.evaluate(() => window.__SKPA__.game.meta.settings.music);
  await page.locator('[data-setting="music"]').click();
  await wait(page, 250);
  const musicAfter = await page.evaluate(() => window.__SKPA__.game.meta.settings.music);
  await page.locator('[data-setting="music"]').click();
  await wait(page, 250);
  const musicRestored = await page.evaluate(() => window.__SKPA__.game.meta.settings.music);
  console.log('SETTINGS MUSIC', JSON.stringify({ musicBefore, musicAfter, musicRestored }));
  await shot('f07-settings');
  await page.locator('.panel-close').first().click();
  await wait(page, 250);
  await page.locator('[data-act="resume"]').click();
  await wait(page, 300);

  // ── Gameover with no gems: revive disabled ──
  await page.evaluate(() => { const g = window.__SKPA__.game; g.meta.gems = 0; g.onPlayerDeath(); });
  await wait(page, 500);
  const reviveDisabled = await page.locator('[data-act="revive"]').count();
  const reviveNeed = await page.locator('.result-actions .btn').first().textContent();
  console.log('GAMEOVER NO GEMS', JSON.stringify({ reviveDisabled, reviveNeed }));
  await shot('f08-gameover-broke');

  console.log('--- LOGS ---');
  console.log(logs.length ? logs.join('\n') : 'clean');
  await browser.close();
})();

