  const biome = BIOMES[this.run.biome];
  const pool = this.room.roomType === 'elite' ? ['brute', 'wraith', 'mage', 'charger'] : ['husk', 'bat', 'archer', 'charger', 'bomber', 'mage', 'wraith', 'brute'];
