const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = (p, ms) => p.waitForTimeout(ms);
(async () => {
  const browser = await chromium.launch({ headless: true });
  for (const [name, vp] of [['d', { width: 1440, height: 900 }], ['m', { width: 390, height: 844 }]]) {
    const ctx = await browser.newContext({ viewport: vp, deviceScaleFactor: name === 'm' ? 2 : 1, isMobile: name === 'm', hasTouch: name === 'm' });
    const page = await ctx.newPage();
    const logs = [];
    page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') logs.push(`[${m.type()}] ${m.text()}`); });
    page.on('pageerror', e => logs.push(`[pageerror] ${e.message}`));
    await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
    await wait(page, 1000);
    await page.evaluate(() => {
      const g = window.__SKPA__.game;
      g.meta.level = 10; g.meta.skillPoints = 3; g.meta.statPoints = 6;
      g.recompute();
    });
    if (name === 'm') await page.tap('#btn-play'); else await page.click('#btn-play');
    await wait(page, 700);
    const gate = page.locator('[data-town="gate"]');
    if (name === 'm') await gate.tap(); else await gate.click();
    await wait(page, 400);
    if (name === 'm') await page.tap('#enter-loop'); else await page.click('#enter-loop');
    await wait(page, 1400);
    if (await page.locator('[data-path]').count()) {
      if (name === 'm') await page.locator('[data-path]').first().tap(); else await page.locator('[data-path]').first().click();
      await wait(page, 700);
    }
    // wait for the wave to spawn
    await wait(page, 2600);
    const info = await page.evaluate(() => {
      const g = window.__SKPA__.game;
      return { mode: g.mode, state: g.roomState, wave: g.wave, enemies: g.enemies.map(e => ({ kind: e.kind, x: Math.round(e.x), y: Math.round(e.y), hp: e.hp, el: e.element })), player: { x: Math.round(g.player.x), y: Math.round(g.player.y), hp: Math.round(g.player.hp) } };
    });
    console.log(name, 'COMBAT', JSON.stringify(info));
    await page.screenshot({ path: `screenshots/${name}09-combat-new.png` });
    // move player toward nearest enemy to show combat
    await page.evaluate(() => {
      const g = window.__SKPA__.game;
      let best = null, bd = 1e9;
      for (const e of g.enemies) { const d = Math.hypot(e.x - g.player.x, e.y - g.player.y); if (d < bd) { bd = d; best = e; } }
      if (best) { g.player.x = best.x - 26; g.player.y = best.y + 6; g.player.invuln = 3; }
    });
    await wait(page, 300);
    await page.screenshot({ path: `screenshots/${name}10-combat-near.png` });
    console.log(name, 'LOGS', logs.length ? logs.join('\n') : 'clean');
    await ctx.close();
  }
  await browser.close();
})();

